WITH payload AS (SELECT $archive_payload$[{"id":"98a8b093-594b-5bef-aa41-a238fe21f8c9","document_type":"judgment","category":"judicial","subcategory":"general","title":"إجارة -مطالبة مستأجر بتسليم عن مؤجرة -الدفع بأن العقد معلق على شرط يتعذر حتقيقه -عدم مشروعية تعليق عقود املعاوضات على شرط مجهول البداية -ثبوت بطان العقد ورد","document_number":"33476296","case_number":"33440498","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/22","year":"1434","subject":"إجارة -مطالبة مستأجر بتسليم عن مؤجرة -الدفع بأن العقد معلق على شرط يتعذر حتقيقه -عدم مشروعية تعليق عقود املعاوضات على شرط مجهول البداية -ثبوت بطان العقد ورد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/12/22 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33476296 :‬‬\n                    ‫َر ْق ُم الدعوى‪33440498 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34218870‬تاريخه‪1434/5/21 :‬هـ‬\n\n\n\n ‫إجــارة ‪ -‬مطالبــة مســتأجر بتســليم عــن مؤجــرة ‪ -‬الدفــع بــأن العقــد‬\n ‫معلــق علــى شــرط يتعــذر حتقيقــه ‪ -‬عــدم مشــروعية تعليــق عقــود‬\n ‫املعاوضــات علــى شــرط مجهــول البدايــة ‪ -‬ثبــوت بطــان العقــد ورد‬\n                                                     ‫دعــوى املدعيــة‪.‬‬\n\n\n\n\n ‫‪ -1‬قــال يف املغنــي جــ‪ 8‬صــ‪»:13‬وإن اكتــرى فســطاط ًا إلــى مكــة ولم يقل‬\n ‫متــى أخــرج فالكــراء فاســد وبــه قــال أبــو ثــور وهــو قيــاس قــول الشــافعي‬\n ‫‪ ،‬وقــال أصحــاب الــرأي‪ :‬يجــوز استحســان ًا بخــاف القيــاس‪ ،‬ولنــا‪ :‬أنهــا‬\n ‫مــدة غيــر معلومــة االبتــداء فلــم يجــز ‪،‬كمــا لــو قــال‪ :‬أجرتــك داري‬\n                          ‫مــن حــن يخــرج احلــاج إلــى آخــر الســنة ‪ )...‬أ‪.‬ه ـ ‪.‬‬\n ‫‪ -2‬كشــاف القنــاع جــ‪ 3‬صــ‪( : 222‬النــوع الثالــث مــن الشــروط الفاســدة‬\n ‫أن يشــترط البائــع شــرط ًا يعلــق البيــع عليــه كقولــه‪ :‬بعتــك إن‬\n                         ‫جئتنــي بكــذا أو بعتــك إن رضــي فــان ‪ )...‬أ‪.‬ه ـ ‪.‬‬\n ‫‪ -3‬الشــرح املمتــع جــ‪ 10‬صــ‪( : 35‬فلــو أجــر ســيارة محركهــا معطــل‬\n ‫للســفر عليهــا ‪ ،‬فــإن اإلجــارة ال تصــح ‪ ،‬وإذا قــال املســتأجر لصاحبهــا‪:‬‬\n ‫متــى أصلحتهــا فقــد اســتأجرتها منــك الشــهر بكــذا وكــذا ‪ ،‬فهنــا ال‬\n ‫تصــح اإلجــارة أيض ـ ًا ؛ ملــا يلــي‪ :‬أوالً‪ :‬أن العقــود واملعاوضــات ال يصــح‬\n ‫تعليقهــا كمــا هــو املذهــب‪ .‬ثاني ـ ًا‪ :‬أن هــذا مجهــول ‪ ،‬أي ابتــداء املــدة‬\n\n                                                                                      ‫‪64‬‬\n\f     ‫مــن التصليــح ‪ ،‬والتصليــح غيــر معلــوم وعلــى هــذا فــا تصــح ‪ ،‬فــإذا‬\n     ‫كان فيهــا خــراب قليــل ونعلــم أنهــا تصلــح خــال يــوم أو يومــن فإنــه‬\n                                                          ‫يجــوز تأجيرهــا) أ‪.‬هــ‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيــة «شــركة» بدعــوى ضــد املدعــى عليــه بأنهــا اســتأجرت‬\n     ‫منــه محطــة وقــود ملــدة خمســة عشــر عامـ ًا تبــدأ مــن تاريــخ اســتالم املوقــع‬\n     ‫ويكــون االســتالم بعــد فراغــه مــن بنائهــا وجتهيزهــا وألنهــا يف مرحلــة‬\n     ‫التشــطيب وعلــى وشــك االنتهــاء وألن املدعــى عليــه خاطبهــا طالبــا‬\n     ‫زيــادة األجــرة أو تقليــل املــدة لــذا فقــد طلــب وكيلهــا إلزامــه بإمضــاء‬\n     ‫العقــد وتســليمها املوقــع فــور الفــراغ منــه ‪ ،‬أقــر وكيــل املدعــى عليــه‬\n     ‫بالعقــد مبــا تضمنــه مــن ثمــن ومــدة وتاريــخ بدايــة وأنهــا ال زالــت حتــت‬\n     ‫أن وكيــل املدعيــة أنكــر مــا ورد يف دفــع وكيــل املدعــى‬          ‫اإلنشــاء إال ّ‬\n     ‫عليــه ‪،‬ولكــون العقــد معلق ـ ًا علــى االســتالم وانتهــاء املؤجــر مــن بنــاء‬\n     ‫احملطــة وجتهيزهــا وألن عقــود املعاوضــات ال يصــح تعليقهــا‪ ،‬وألن‬\n     ‫اجلهــل بزمــان ابتــداء العقــد يــؤدي إلــى اجلهــل مبدتــه وهــذا يبطلــه عليــه‬\n     ‫فقــد قــررت الدائــرة ثبــوت بطــان العقــد الــذي تعاقــد عليــه املتداعيــان‬\n     ‫أعــاه وصرفــت النظــر عــن دعــوى املدعــي وبــه حكمــت ‪ ،‬قــرر وكيــل‬\n     ‫املدعيــة االعتــراض فأفهــم بالتعليمــات ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                             ‫االســتئناف‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f‫العامــة‬\n   ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي يف احملكمــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫العامــة مبحافظــة القطيــف برقــم ‪ 33440498‬وتاريــخ‬              ‫َ‬     ‫احملكمــة‬\n‫‪ 1433/07/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331241998‬وتاريــخ‬\n‫‪1433/07/02‬هـ حضر (‪ )......‬ســعودي اجلنســية مبوجب الســجل املدني‬\n‫ا عــن شــركة (‪ )......‬مبوجــب الوكالــة رقــم‬      ‫رقــم (‪ )......‬بصفتــه وكيـ ً‬\n‫(‪ )7684‬يف ‪1433/1/11‬ه ـ الصــادرة مــن كتابــة العــدل بــوزارة التجــارة‬\n‫والصناعــة بالريــاض وحضــر حلضــوره (‪ )......‬ســعودي اجلنســية بالســجل‬\n‫ا عــن املدعــى عليــه (‪ )......‬ســعودي‬   ‫املدنــي رقــم (‪ ).....‬بصفتــه وكي ـ َ‬\n‫اجلنســية بالســجل املدني رقم (‪ )......‬مبوجب الوكالة رقم (‪ )9‬الصادرة‬\n‫مــن كتابــة عــدل رأس تنــورة يف ‪1433/07/14‬ه ـ وادعــى املدعــي‬\n‫وكالــة قائ ـاَ‪ :‬إنــه يف ‪1430/07/11‬ه ـ اســتأجر موكلــي احملطــة‬\n‫الواقعــة علــى طريــق ‪ .......‬بعــد نقطــة التفتيــش يف بدايــة طريــق ‪ .......‬مــن‬\n‫مالكهــا (‪ )......‬والــذي ميلكهــا مبوجــب الصــك الصــادر مــن كتابــة‬\n‫عــدل القطيــف برقــم ‪/83‬ق يف ‪1422/8/26‬ه ـ بأجــرة ســنوية مقدارهــا‬\n‫مليــون ريــال ملــدة خمســة عشــر عام ـ َا ويبــدأ ســريان العقــد مــن تاريــخ‬\n‫اســتالم املوقــع ‪ ،‬ويكــون االســتالم بعــد انتهــاء املالــك مــن بنــاء احملطــة‬\n‫وجتهيزها واحملطة اآلن على وشــك االنتهاء فهي يف مرحلة التشــطيبات‬\n‫وقــد خاطــب املدعــى عليــه موكلــي طالبـ َا زيــادة األجرة عمــا مت التعاقد‬\n‫عليــه لتكــون ‪ 1.500.000‬ريــال ملــدة خمســة عشــر ســنة أو ‪1.300.000‬‬\n‫ريــال ملــدة عشــر ســنوات أو ‪ 1.200.000‬ريــال ملــدة خمــس ســنوات‬\n\n                                                                                       ‫‪66‬‬\n\f     ‫وحيــث األمــر مــا ذكــر فإنــي أطلــب إمضــاء العقــد علــى مــا هــو عليــه‬\n     ‫وإلــزام املدعــى عليــه بتســليمنا املوقــع بعــد انتهائــه مــن جتهيــزه هكــذا‬\n     ‫ادعــى وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ورد يف دعــوى‬\n     ‫املدعــي مــن العقــد املذكــور بالثمــن املذكــور والتاريــخ املذكــور‬\n     ‫فصحيــح ومــا ورد مــن طلــب موكلــي زيــادة اإليجــار فــا أعلــم عنــه‬\n     ‫وســأراجع موكلــي يف ذلــك وموكلــي ممتنــع عــن تســليم احملطة ويطلب‬\n     ‫فســخ العقــد ملــا هــو مذكــور يف مذكــرة الدفــاع هكــذا أجــاب ثــم قــدم‬\n     ‫مذكــرة دفــاع هــذا نصهــا ( ‪ -1‬تعاقــد موكلــي مــع املدعيــة بتاريــخ‬\n     ‫‪1430/07/11‬ه ـ علــى تأجيرهــا محطــة احملروقــات الواقعــة علــى طريق‬\n     ‫‪ - .......‬الدمــام التــي كانــت قيــد اإلنشــاء ولــم تكتمــل بعــد بأجــرة‬\n     ‫ســنوية قدرهــا مليــون ريــال (البنــد ‪ 3‬مــن عقــد اإليجــار) (املرفــق رقــم‬\n     ‫‪ -2 )-1-‬نــص البنــد ( ‪ 2‬مــن العقــد املنــوه عنــه) علــى أن مــدة ‪ :‬عقــد‬\n     ‫اإليجــار (‪ )15‬ســنة هجريــة تبــدأ مــن تاريــخ إيصــال التيــار الكهربائــي‬\n     ‫وتركيــب عــدادات شــركة الكهربــاء للموقــع واســتالم ترخيــص‬\n     ‫البنــاء ‪ ،‬وهــذا يعنــي وفقـ ًا ملنطــوق نــص الفقــرة املنــوه عنهــا مــن بنــد (‪)2‬‬\n     ‫أن يكــون التاريــخ املعــول عليــه لبدايــة العقــد هــو املســائل الثــاث‬\n     ‫املذكــورة أعــاه ‪ -3‬كمــا وردت عبــارة يف ذات البنــد املشــار إليــه أعاله‬\n     ‫علقــت بدايــة العقــد علــى التســليم مبوجــب محضــر اســتالم للعــن محــل‬\n     ‫العقــد معتمــد مــن الطرفــن بنصهــا يف الســطر الثالــث مــن البنــد‬\n     ‫املذكــور علــى أن (وال يعتمــد بدايــة العقــد إال مبوجــب محضــر اســتالم‬\n     ‫املوقــع معتمــد مــن الطرفــن) ‪ -4‬تعــذر علــى موكلــي تســليم العــن‬\n     ‫املؤجــرة للمدعيــة ألســباب خارجيــة عــن إرادتــه ممــا جتعــل التزامــه‬\n     ‫ا وترجــع اســتحالته‬   ‫ال ممــا يجعــل العقــد باط ـ ً‬   ‫بتســليم العــن مســتحي ً‬\n\n\n‫‪67‬‬\n\f‫قــدرة موكلــي علــى تســليم العــن املؤجــرة بســبب اآلتــي‪ :‬أ‪-‬رفضــت‬\n‫اجلهــات املختصــة منــح موكلــي ترخيــص إقامــة احملطــة يف املــكان‬\n‫املتعاقــد علــى تأجيــره للشــركة املدعيــة لكــون األرض املشــيدة علــى‬\n‫جــزء منهــا احملطــة موضــوع الدعــوى هــي أرض زراعيــة ورغــم إســتيفاء‬\n‫موكلــي جميــع الطلبــات إال أن وزارة الزراعــة مــا زالــت ترفــض فــرز‬\n‫جــزء مــن األرض للمحطــة ‪ ،‬والشــك أنــه بغيــر الترخيــص الصــادر مــن‬\n‫اجلهــات املختصــة ال ميكــن للشــركة املدعيــة مزوالــة عملهــا لتشــغيل‬\n‫وإدارة احملطــة موضــوع الدعــوى وبــدون الترخيــص يصبــح موكلــي غيــر‬\n‫قــادر علــى تســليم احملطــة للمســتأجر ممــا يجعــل تنفيــذ التزامــه بتســليم‬\n‫املأجــور للمســتأجر التزام ـ ًا مســتحيل التنفيــذ ممــا يكــون واجــب‬\n‫الفســخ ال ســيما وأن موكلــي منــذ تاريــخ إبرامــه عقــد اإليجــار وحتــى‬\n‫تاريخــه يراجــع اجلهــات املختصــة دون نتيجــة أي منــذ ثــاث ســنوات ب‪-‬‬\n‫أن ملوكلــي شــريك يف احملطــة بحصــة النصــف وهــو الشــريك (‪).......‬‬\n‫وقــد أبــدى معارضتــه علــى قيــام موكلــي بتأجيــر احملطــة دون اســتئذانه‬\n‫(املرفــق‪ )-2-‬ورفــض إجــازة تصــرف موكلــي بحصة الشــريك املذكور‬\n‫بتأجيــره نيابــة عنــه‪ -5 .‬قــام موكلــي بإخطــار الشــركة املدعيــة بعــدم‬\n‫قدرتــه علــى تنفيــذ التزامــه بتســليم املأجــور للمدعيــة مرتــن (املرفــق‬\n‫رقــم ‪ )-3-‬وأخطرهــا بفســخ العقــد املبــرم بينــه وبــن املدعيــة الســتحالة‬\n‫التنفيــذ إال أن املدعيــة أصــرت علــى طلبهــا بتســليم احملطــة ويف ذلــك‬\n‫مخالفــة لألنظمــة الســارية يف اململكــة‪ -6 .‬أن العقــد قــد أبــرم بــن‬\n‫موكلــي واملدعيــة موقوفــا ً علــى شــرط إيصــال التيــار الكهربائــي‬\n‫وتركيــب العــدادات واســتالم تراخيــص البنــاء وتراخيــص التشــغيل‬\n‫وبعــدم احلصــول علــى التراخيــص املذكــورة فيعتبــر العقــد مفســوخ ًا‬\n\n\n                                                                                   ‫‪68‬‬\n\f     ‫لعــدم حتقــق الشــرط الفاســخ‪ -7 .‬أن موكلــي لــم يســتلم بــدل األجــرة‬\n     ‫حتــى تاريخــه رغــم مضــي ثــاث ســنوات لكــي ميكــن القــول بإلزاميــة‬\n     ‫العقــد بينــه وبــن املدعيــة‪ .‬صاحــب الفضيلــة أن تســليم العــن املأجــورة‬\n     ‫لــم يتــم ودفــع األجــرة لــم يتــم أيض ـ ًا ويســتحيل علــى موكلــي تســليم‬\n     ‫املأجــور ملــا يتــم بيانــه أعــاه ممــا يعنــي أن العقــد املبــرم بــن موكلــي‬\n     ‫وبــن املدعيــة قــد انعقــد مــع تخلــف أهــم األركان األساســية لالنعقــاد‬\n     ‫ممــا يعنــي بطــان العقــد لــذا ألتمــس مــن فضيلتكــم رد دعــوى املدعيــة)‬\n     ‫انتهــى نصهــا وأضــاف املدعــى عليــه وكالــة قائ ـاً‪ :‬إن رغــب املدعــي‬\n     ‫اســتالم املوقــع علــى مــا هــو عليــه اآلن دون مطالبتنــا بشــيء فــا مانــع‬\n     ‫لدينــا هكــذا أجــاب ويف جلســة أخــرى حضــر املدعــي وكالــة‬\n     ‫ا عــن‬‫‪ .....................‬ســعودي بالســجل املدنــي رقــم ‪ ....................‬وكي ـ ً‬\n     ‫شــركة ‪ .....................‬مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل‬\n     ‫يف وزارة التجــارة والصناعــة برقــم ‪ 7683‬وتاريــخ ‪1433/01/11‬ه ـ جلــد‬\n     ‫‪ 266‬وحضــر حلضــوره املدعــى عليــه وكالــة وســبق أن حــدد للطرفــن‬\n     ‫موعـ ٌـد يف ‪1433/8/17‬ه ـ وكنــت يف إجازة اضطرارية وبســؤال املدعي‬\n     ‫ا ‪ :‬إنــي لــدي مذكــرة‬     ‫عمــا اســتعد بــه يف اجللســة املاضيــة أجــاب قائ ـ ً‬\n     ‫جوابيــة وأطلــب االطــاع عليهــا ‪ ،‬وقــد جــرى االطــاع عليهــا ورأيــت‬\n     ‫ضبطهــا وهــذا نــص احلاجــة منهــا ‪ :‬أوال ‪( :‬وال يخفــى علــى فضيلتكــم‬\n     ‫قــول اهلل ســبحانه وتعالــى {يــا أيهــا اللذيــن آمنــوا أوفــوا بالعقــود} ‪،‬‬\n     ‫واملدعــى عليــه يريــد أن يخالــف هــذا األمــر الشــرعي املتــن وأن ينقــض‬\n     ‫العقــد بــدون مبــرر شــرعي ( مرفــق صــورة العقــد) واحلامــل لــه علــى ذلــك‬\n     ‫هــو طمعــه يف زيــادة األجــرة ‪ ،‬وكان االتفــاق معــه حســب العقــد أن‬\n     ‫تكــون أجــرة احملطــة ‪ :‬مليــون ريــال ســنوي ًا ‪ ،‬وممــا يؤكــد هــذا‬\n\n\n‫‪69‬‬\n\f‫لفضيلتكــم هــو خطابــه املوجــه لنــا يف تاريــخ ‪1433/1/3‬ه ـ ( مرفــق‬\n‫صــورة ) حيــث يقــول فيــه مانصــه ‪ ( :‬اإلجــار قليــل الوقــت احلاضــر حيــث‬\n‫اخلســارة الكبيــرة ومســاحة احملطــة كبيــرة ‪ 25,000‬الــف متــر حســب‬\n‫الكروكــي املرفــق املطلــوب ‪ -1‬إن كان مــدة اإلجــار خمســة عشــر‬\n‫ســنة يكــون اإلجــار مليــون ونصــف ‪ -2‬إن كان مــدة اإلجــار عشــر‬\n‫ســنوات يكــون اإلجــار مليــون وثــاث مائــة ألــف ريــال ‪ -3‬إن كان مــدة‬\n‫اإلجــار خمــس ســنوات يكــون اإلجــار مليــون ومائتــا ألــف حيــث تقــدم‬\n‫لنــا عــدد مــن الشــركات واألفــراد بعــرض كبيــر ولكــن الرغبــة‬\n‫بشــركة (‪ ).......‬حيــث الشــركة عمالقــة وســمعه فــوق املمتــازة ‪) ...‬‬\n‫انتهــى هــذا نــص كالمــه ‪ ،‬واحلمــدهلل الــذي أظهــر احلــق علــى لســانه وال‬\n‫يخفــى علــى فضيلتكــم أنــه اليحــق لــه الزيــادة علــى األجــرة بعــد توقيــع‬\n‫العقــد وتفــرق املتعاقديــن ‪ ،‬لقولــه صلــى اهلل عليــه وســلم ( البيعــان‬\n‫باخليــار مالــم يتفرقــا ) ثاني ـ ًا ‪ :‬ماجــاء يف مذكــرة وكيــل املدعــى عليــه‬\n‫(فقــرة ‪/4‬أ ) مــن قولــة بــأن اجلهــات املختصــة رفضــت منــح موكلــه‬\n‫ترخيــص إقامــة احملطــة فاجلــواب عنــه أن هــذا الــكالم غيــر صحيــح ‪،‬‬\n‫وأن احملطــة قائمــة وقــد أنشــئت ‪ ،‬وال يســتطيع أن يبنيهــا بــدون فســح‬\n‫بنــاء ‪ ،‬وال يعطــى فســح البنــاء مــن البلديــة إال بعــد موافقــة اجلهــات‬\n‫املختصــة ذات العالقــة ( وزارة النقــل والدفــاع املدنــي واملــرور ) وهــل هــذا‬\n‫الرفــض رفضـ ًا مطلقـ ًا ال يجــوز بــأي حــال مــن األحــوال فتــح احملطــة‪ ،‬أم‬\n‫ـض مشــروط بإحضــار طلبــات وإجــراءات اعتياديــة كأي محطــة‬             ‫أنــه رفـ ٌ‬\n‫أخــرى ؟ وممــا يــدل علــى عــدم صدقــه هــو قولــة يف خطابــه املوجــه‬\n‫ملوكلــي بتاريــخ ‪1433/6/15‬ه ـ ‪ ( :‬وملوافقتنــا علــى اقتراحــه بــأن نقــوم‬\n‫بتشــغيلها بأنفســنا) انتهــى‪ .‬وهــذا دليــل علــى أن اجلهــات املختصــة موافقة‬\n\n\n                                                                                       ‫‪70‬‬\n\f     ‫علــى منحــه الترخيــص ‪ ،‬وإمنــا يريــد أن يشــغلها هــو بنفســه ‪ ،‬فلــو لــم‬\n     ‫تســمح اجلهــات املختصــة ملــا متكــن هــو وال غيــره مــن تشــغيلها ثالث ـ ًا ‪:‬‬\n     ‫ماجــاء يف مذكــرة وكيــل املدعــى عليــه ( فقــرة ‪/4‬ب ) وهــو قولــه ( أن‬\n     ‫ملوكلــي شــريك يف احملطــة بحصــة النصــف وهــو الشــريك ‪...................‬‬\n     ‫وقــد أبــدا معارضتــه علــى قيــام موكلــي بتأجيــر احملطــة دون اســتئذانه‬\n     ‫( املرفــق‪ )-2-‬ورفــض إجــازة تصرف موكلي بحصة الشــريك املذكور‬\n     ‫بتأجيــره نيابــة عنــه ) انتهــى ‪ .‬واجلــواب عــن هــذا الدفــع هــو ماجــاء يف‬\n     ‫نــص العقــد املوقــع مــن الطرفــن ‪ ،‬يف البنــد رقــم ســتة ونصــه ‪ :‬يقــر‬\n     ‫الطــرف األول بأنــه املالــك الوحيــد للمحطــة وملحقاتهــا وأنهــا شــيدت‬\n     ‫وفــق اللوائــح والنضــم الســارية باململكــة وال ينازعــه فيهــا أحــد ولــم‬\n     ‫يســبق لــه وأن قــام بتأجيرهــا لنفــس فتــرة العقــد وأننهــا ليســت محملــة‬\n     ‫بــأي إلتزامــات ماديــة ‪ ...‬انتهــى فهــذا شــرط واضــح فالعقــد يثبــت‬\n     ‫لفضيلتكــم بأنــه عنــد تأجيرهــا لــم يكــن لــه شــريك فيهــا ‪ ،‬وإن كان‬\n     ‫صادق ـ ًا يف كالمــه فــإن هــذا نــوع مــن التالعــب واالحتيــال ( أحتفــظ‬\n     ‫بحقــي يف طلــب تعزيــره ) وممــا يؤكــد لفضيلتكــم عــدم صحة كالمه‬\n     ‫بــأن لــه شــريك يف احملطــة ‪ ،‬هــو صــك التملــك ألرض احملطــة ‪ ،‬فــإن‬\n     ‫صــك التملــك الــذي زودنــا املدعــى عليــه بنســخة منــه عنــد التعاقــد يفيــد‬\n     ‫بأنــه هــو املالــك الوحيــد وليــس معــه شــريك فيهــا ( مرفــق صــورة ) حيــث‬\n     ‫جــاء يف صــك التملــك مانصــه ‪ ( :‬إن وزيــر الزراعــة وامليــاه اســتناد ًا علــى‬\n     ‫املــادة التاســعة مــن نضــام توزيــع األراضــي البــور الصــادر باملرســوم‬\n     ‫امللكــي رقــم م‪ 26/‬يف ‪ 1388/7/6‬ه ـ وانفــاذ ًا ملصادقــة املقــام الســامي‬\n     ‫بتملــك هــذه األرض رقــم ‪/1165/4‬م وتاريــخ ‪ 1421/9/14‬ه ـ وبنــاء‬\n     ‫علــى قــرار التوزيــع رقــم ‪ 63607‬وتاريــخ ‪ 1416/9/ 21‬ه ـ يقــرر مايلــي ‪:‬‬\n\n\n‫‪71‬‬\n\f‫ميلــك (‪ ).......‬القطعــة رقــم واحــد مــن األرض الواقعــة (‪ )).......‬انتهــى وجــاء‬\n‫يف آخــر صــك التملــك مــا نصــه ‪ ( :‬وقــرر املنــدوب املذكــور تنازلــه عــن‬\n‫األرض املوصوفــة بعاليــه وهــي خاليــة وغيــر مشــغولة لهــذا احلاضــر معــي‬\n‫باملجلــس الشــرعي ‪ ).......( /‬رقــم احلفيظــة (‪ ).......‬يف ‪1398/1/1‬ه ـ‬\n‫الريــاض رقــم ســجل املدنــي ‪ 1050094117‬وقــد قبــل (‪ ).......‬املذكــور‬\n‫هــذه األرض وصــادق علــى كل مــا ذكــر بحضــور شــاهدي احلــال‬\n‫ـاء علــى مــا تقــدم فقــد ثبــت لــدي مــا ذكــر بعاليــه‬  ‫املعرفــن (‪ ).......‬وبنـ ً‬\n‫شــرعاً) وعلــى فــرض صحــة كالم وكيــل املدعى عليه بأن له شــريك ًا‬\n‫يف احملطــة وأنــه باعــه جــزء ًا منهــا بعــد تعاقــده معنــا ‪ ،‬فــإن هــذا ال يؤثــر‬\n‫علــى عقــد اإلجــارة بــن الطرفــن ‪ ،‬حيــث جــاء يف البنــد ‪ 18‬مــن عقــد‬\n‫اإلجــارة مانصــه ‪ :‬يف حــال انتقــال ملكيــة احملطــة لطــرف آخــر خــال‬\n‫مــدة ســريان العقــد يســري هــذا العقــد بكامــل شــروطه مــع املالــك‬\n‫اجلديــد حتــى انتهــاء مدتــه ‪ ،‬وعلــى الطــرف األول املؤجــر إخطــار املالــك‬\n‫اجلديــد بهــذا الشــرط قبــل إمتــام عمليــة البيــع ‪ ،‬كمــا يســري مفعــول هــذا‬\n‫العقــد يف مواجهــة ورثــة الطرفــن يف حــال الوفــاة ‪ .‬انتهــى وال يخفــى علــى‬\n‫فضيلتكــم أن هــذا الشــرط رقــم (‪ )18‬هــو مــن بــاب التأكيــد ‪ ،‬ولــو لــم‬\n‫ُيشــرط فــإن القاعــدة الشــرعية تــدل عليــه وهــي ( أن املســتأجر قــد ملــك‬\n‫املنفعــة ) فاملســتأجر يف هــذا احلــال أحــق مبنفعــة العــن مــن املشــتري‬\n‫اجلديــد ‪ ،‬ألنــه اســتحقها قبلــه ‪ .‬رابع ـ ًا ‪ :‬مــا جــاء يف مذكــرة وكيــل‬\n‫املدعــى عليــه (بنــد ‪ )5‬وهــو ادعائــه بــأن موكلــه قــام بإخطــار املدعيــة‬\n‫بعــدم قدرتــه علــى تنفيــذ التزامــه بتســليم املأجــور للمدعيــة مرتــن ‪....‬‬\n‫فاجلــواب عنــه أن هــذا ادعــاء غيــر صحيــح بــل إن املدعــى عليــه أخطــر‬\n‫موكلــي املدعــي بطلبــه زيــادة األجــرة ‪ ( ،‬مرفــق صــورة مــن خطــاب‬\n\n\n                                                                                          ‫‪72‬‬\n\f     ‫املدعــى عليــه ) ‪ ،‬وملــا رفــض موكلــي زيــادة األجــرة أخطــره بفســخ‬\n     ‫العقــد ‪ .‬فضيلــة الشــيخ ‪ :‬ممــا يثبــت لفضيلتكــم عــدم صــدق وكيــل‬\n     ‫املدعــي يف كالمــه هــو أن املدعــى عليــه يريــد تشــغيل احملطــة بنفســه ‪،‬‬\n     ‫وقــد جــاء هــذا ‪ ،‬هــو قــول املدعــى عليــه يف خطابــه املوجــه ملوكلــي‬\n     ‫بتاريــخ ‪1433/06/15‬ه ـ ونصــه ‪ ( :‬وملوافقتنــا علــى اقتراحــه بــأن نقــوم‬\n     ‫بتشــغيلها بأنفســنا ) انتهــى فاملدعــى عليــه متناقــض يف كالمــه تــار ًة‬\n     ‫يزعــم أنــه عاجــز عــن تســليمها ‪ ،‬وتــار ًة يطلــب زيــادة األجــرة ‪ :‬وتــار ًة‬\n     ‫يتعلــل بأنــه يريــد أن يقــوم بتشــغيل احملطــة بنفســه ‪ .‬خامسـ ًا ‪ :‬مــا جــاء يف‬\n     ‫مذكــرة وكيــل املدعــى عليــه (بنــد‪ )6‬وادعائــه أن العقــد موقوفـ ًا علــى‬\n     ‫شــرط إيصــال الكهربــاء وتركيــب العــداد واســتالم تراخيــص البنــاء‬\n     ‫وتراخيــص التشــغيل ‪ ،‬وإال فيعتبــر العقــد مفســوخ ًا ‪ ....‬فاجلــواب عنــه أن‬\n     ‫كالمــه غيــر صحيــح ‪ ،‬وأن التعاقــد قــد مت بــن الطرفــن ولكــن بدايــة‬\n     ‫احتســاب األجــرة تبــدأ مــن تاريــخ إيصــال التيــار الكهربائــي وتركيــب‬\n     ‫كافــة عــدادات شــركة الكهربــاء للموقــع واســتالم ترخيــص البنــاء‬\n     ‫وهــذا كلــه منصــوص عليــه يف العقــد يف البنــد رقــم (‪ )2‬وعلــى حســب‬\n     ‫علمنــا فإنــه قــد مت إنهــاء كافــة اإلجــراءات وموافقــة اجلهــات املختصــة ‪،‬‬\n     ‫وليــس هنــاك مانــع نظامــي مينــع املدعــى عليــه مــن الســماح بتشــغيل‬\n     ‫احملطــة ‪ .‬سادس ـ ًا ‪ :‬مــا جــاء يف مذكــرة وكيــل املدعــى عليــه (بنــد‪)7‬‬\n     ‫وهــو قولــه إن موكلــه لــم يســتلم األجــرة حتــى تاريخــه رغــم مضــي ثــاث‬\n     ‫ســنوات لكــي ميكــن القــول بإلزاميــة العقــد بينــه وبــن موكلــي املدعي‬\n     ‫فاجلــواب عنــه هــو أن عقــد اإلجــارة يلــزم باإليجــاب والقبــول ‪ ،‬وقــد مت‬\n     ‫هــذا ‪ ،‬وقــد اتفــق الطرفــان علــى أن الدفــع ال يكــون إال بعــد جتهيــز‬\n     ‫احملطــة وتســيلمها ‪ ،‬فهــذا ليــس عائقـ ًا وال مبــرر ًا للمدعــى عليــه ليتنصــل‬\n\n\n‫‪73‬‬\n\f‫مــن العقــد‪ .‬فضيلــة الشــيخ ‪ :‬إن املدعــى عليــه يريــد أن ينقــض العقــد‬\n‫بــدون مبــرر شــرعي ‪ ،‬وممــا يثبــت هــذا لفضيلتكــم هــو قولــه يف خطابــه‬\n‫املوجه إلى موكلي يف ‪1433/07/01‬هـ ‪ ،‬يف آخر ســطر منه ‪ ،‬ونصه‪:‬‬\n‫(وكل إنســان حــر يف حاللــه ) وقولــه هــذا غيــر صحيــح‪ ،‬واحلريــة مقيــدة‬\n‫بالقيــود الشــرعية ‪ ،‬ممــا يثبــت لفضيلتكــم عــدم التزامــه بالقيــود‬\n‫والقواعــد الشــرعية والقانونيــة وعــدم معرفتــه بالفــرق بــن العقــود‬\n‫الالزمــة والعقــود اجلائــزة ‪ .‬وختام ـ ًا أطلــب مــن فضيلتكــم تذكيــر‬\n‫املدعــى عليــه باملبــادئ اإلســامية واألخالق النزيهــة يف التعامل التجاري‬\n‫وأطلــب ‪ -1‬إلــزام املدعــى عليــه بالوفــاء بالعقــد وتســليم احملطــة حســب‬\n‫األجــرة املتفــق عليهــا بــن الطرفــن ‪ -2‬إلــزام املدعــى عليــه بدفــع تعويض‬\n‫عــن تأخــره يف تســليم احملطــة ‪ ،‬إذا كان تأخــره بــدون عــذر ‪ -3‬إلــزام‬\n‫املدعــى عليــه بدفــع أتعــاب احملامــاة ‪ ).‬انتهــى نصهــا ‪ .‬فطلــب املدعــى‬\n‫عليــه نســخة منهــا فتــم تســليمه نســخة منهــا ويف جلســة أخــرى حضــر‬\n‫الطرفــان وقــد أحضــر وكيــل املدعــى عليــه مذكــرة دفاعيــة رد ًا علــى‬\n‫مذكــرة وكيــل املدعــي وهــذا نصهــا‪( :‬رد ًا علــى مــا تضمنتــه مذكــرة‬\n‫وكيــل املدعيــة املقدمــة لفضيلتكــم يف جلســة يــوم ‪1433/10/29‬ه ـ ‪،‬‬\n‫وجــلُّ مــا حوتــه هــو تبريــرات واهيــة يف‬  ‫ـأت بجديــد ‪ُ ،‬‬  ‫ورغــم أنهــا لــم تـ ِ‬\n‫محاولــة يائســة منــه لاللتفــات علــى احلقيقــة الســاطعة التــي مفادهــا أن‬\n‫عقــد اإليجــار موضــوع الدعــوى قــد ُو ِلـ َـد وهــو معــه أســباب موتــه لتخلــف‬\n‫أهــم الشــروط الشــرعية لصحتــه وانعقــاده‪ .‬ومــع احتفاظنــا بكافــة‬\n‫الدفــوع التــي أوردناهــا يف مذكرتنــا الســابق تقدميهــا لفضيلتكــم يف‬\n‫جلســة يــوم ‪1433/07/14‬ه ـ ‪ ،‬فإننــا جنمــل لفضيلتكــم ردنــا علــى‬\n‫املذكــرة املنــوه عنهــا علــى النحــو التالــي‪ )1( :‬أشــارت مذكــرة وكيــل‬\n\n\n                                                                                          ‫‪74‬‬\n\f     ‫املدعيــة يف الفقــرة (أوالً) منهــا إلــى أن العامــل األساســي ملوكلــي يف‬\n     ‫طلــب فســخ العقــد هــو طمعــه يف زيــادة األجــرة حســب زعمــه ويدلــل علــى‬\n     ‫ذلــك بخطــاب موكلــي لــه املــؤرخ يف ‪1433/01/03‬هــ‪ .‬وقــد تغافــل‬\n     ‫وكيــل املدعيــة عــن حقيقــة مفادهــا أن عقــد اإليجــار قــد أبــرم بــن‬\n     ‫موكلــي وبــن املدعيــة بتاريــخ ‪1430/07/11‬ه ـ ‪ ،‬أي منــذ مــا يزيــد على‬\n     ‫ثــاث ســنوات دون أن يســتلم موكلــي بــدل اإليجــار ‪ ،‬حتــى ميكننــا‬\n     ‫القــول باســتفادته مــن العقــد ‪ ،‬ورغــم مضــي ثــاث ســنني وزيادة األســعار‬\n     ‫يف الســوق ملــا مياثلهــا مــن محطــات واســتالم موكلــي للكثيــر مــن‬\n      ‫العــروض التــي تفــوق بــدل اإليجــار املتفــق عليــه مــع املدعيــة ‪ ،‬فذلــك يــدلّ‬\n     ‫داللــة واضحــة علــى تضــرر موكلــي مــن عقــد موقــوف لــم يحقــق املرجــو‬\n     ‫منــه وهــو االســتفادة ماليـ ًا مــن اســتثمار احملطــة موضــوع الدعــوى رغــم‬\n     ‫أنــه قــد تكبــد مبالــغ باهظــة يف بناءهــا وجتهيزهــا‪ )2( .‬إن الترخيــص‬\n     ‫للمحطــة موضــوع الدعــوى قــد أوضحنــا املقصــود بــه يف مذكرتنــا‬\n     ‫الســابقة ‪ ،‬حيــث أن األرض املقامــة عليهــا احملطــة هــي أرض زراعيــة‬\n     ‫وهــي جــزء مــن مزرعــة موكلــي ولدينــا اآلن معاملــة دائــرة بــن وزارة‬\n     ‫الزراعــة وبــن الدوائــر املختصــة األخــرى لفــرز أرض احملطــة عن املزرعة‬\n     ‫العائــدة ملوكلــي املدعــى عليــه ولــن يصــدر ترخيــص احملطــة إال بعــد‬\n     ‫انتهــاء عمليــة الفــرز وصــدور الصــك اخلــاص باحملطــة‪ )3( .‬إن شــريك‬\n     ‫موكلــي يف احملطــة املدعــو‪ ...‬هــو ليــس شــريك ًا يف أرض احملطــة ‪ ،‬بــل‬\n     ‫إن الشــراكة يف احملطــة فقــط ‪ ،‬حيــث قــام الشــريك املذكــور بتحمــل‬\n     ‫نفقــات وتكاليــف إنشــاء احملطــة مقابــل حصتــه يف اســتثمارها ومعاملــة‬\n     ‫إثبــات شــراكته جاريــة أيضـ ًا لــدى اجلهــات املختصــة ( مرفــق صــورة مــن‬\n     ‫عقــد الشــراكة) ‪ ،‬وال شــك يف أن رفــض شــريك موكلــي إجــازة‬\n\n\n‫‪75‬‬\n\f‫اإلجــارة التــي أجراهــا موكلــي دون علمــه جتعــل مــن املســتحيل علــى‬\n‫موكلــي تســليم املأجــور ‪ ،‬حيــث أنــه وفقـ ًا للقواعــد الشــرعية العامــة ‪،‬‬\n‫إمنــا تنفــذ اإلجــارة مــن الشــريك يف حصتــه فقــط يف حالــة عــدم إجــازة‬\n‫الشــريك اآلخــر وإنــه مــن املعلــوم اســتحالة تبعيــض إيجــار احملطــة إلــى‬\n‫حصــص فبالتالــي يســتحيل علــى موكلــي تســليمها للمدعيــة‪ )4( .‬أمــا‬\n‫مــا جــاء مــن احتجــاج وكيل املدعية ببعض بنود عقــد اإليجار باعتبارها‬\n‫ا ضــد موكلــي فيمــا تضمنتــه ‪ ،‬فهــذا االحتجــاج مــردود عليــه وال‬        ‫دليـ ً‬\n‫تقــوم بــه أي حجــة ضــد موكلــي ‪ ،‬ذلــك أن هــذا العقــد مطبــوع علــى ورق‬\n‫املدعيــة وبنــوده محــررة مــن قبــل املدعيــة ذاتهــا ولــم يتسـ َـن ملوكلــي‬\n‫مراجعتــه أو دراســته أو عرضــه علــى أنــاس مختصــن ‪ ،‬وإمنــا وقعــه حاملــا‬\n‫ا عــن‬ ‫تســلمه مــن املدعيــة ‪ ،‬وبذلــك ال يعتبــر حجــة ضــد موكلــي ‪ ،‬فضـ ً‬\n‫أهــم أركان هــذا العقــد قــد تخلفــت وهــي عــدم قــدرة املؤجــر علــى‬\n‫تســليم املأجــور وعــدم ســداد األجــرة مــن املدعيــة (املســتأجر) فــا يعتبــر‬\n‫العقــد بالتالــي منعقــد ًا (‪ )5‬إن تخلــف شــروط االنعقــاد يف عقــد اإليجــار‬\n‫ا ال نفــاذ لــه بحــق موكلــي وال أثــر‬\n                                       ‫موضــوع الدعــوى جتعلــه عقــد ًا باطـ ً‬\n‫يترتــب عليــه وشــروط انعقــاد عقــد اإليجــار ‪ ،‬كمــا ال يخفــى علــى‬\n‫فضيلتكــم إضافــة إلــى اإليجــاب والقبــول ‪ ،‬هــي ‪( :‬أ) القــدرة علــى‬\n‫تســليم املأجــور ‪ ،‬وقــد تخلــف هــذا الشــرط علــى النحــو الســابق تفصيلــه‬\n‫يف مذكرتنــا الســالف تقدميهــا لفضيلتكــم واملذكــورة أعــاه ‪ ،‬فــا‬\n‫نــرى داعي ـ ًا لتكــراره‪( .‬ب) عــدم اســتالم موكلــي بــدل اإليجــار املتفــق‬\n‫تضمــن العقد‬‫عليــه رغــم مضــي ثــاث ســنني علــى إبــرام العقــد‪( .‬ج) عــدم ّ‬\n‫ذاتــه بيــان تاريــخ واضــح ومحــدد لبــدء ســريان اإليجــار علــى النحــو‬\n‫ا أيض ـ ًا يف مذكرتنــا املنــوه عنهــا أعــاه ‪ ،‬وهــذا‬   ‫الســابق بيانــه تفصي ـ ً‬\n\n\n                                                                                      ‫‪76‬‬\n\f     ‫ا أيضـاً‪.‬‬ ‫بــا شــك يجعــل العقــد منطويـ ًا علــى غــرر وجهالــة جتعلــه باطـ ً‬\n     ‫صاحــب الفضيلــة أنــه وفق ـ ًا للقواعــد الشــرعية ‪ ،‬فــإن عقــد اإليجــار‬\n     ‫الــذي يحــاول وكيــل املدعيــة التشــبث بــه وبلزوميتــه ضــد موكلــي ‪،‬‬\n     ‫نكيفــه التكييــف الشــرعي ‪ ،‬فأقــلّ مــا يقــال عنــه‬ ‫ّ‬       ‫إمنــا هــو إذا أردنــا أن‬\n     ‫أنــه وعــد باإليجــار وليــس عقــد إيجــار وال شــك أن هــذا الوعــد وملــا‬\n     ‫انطــوى عليــه مــن جهالــة وغــرر وضــرر وتخلــف شــرط التســليم‬\n     ‫واســتحالتها وعــدم ســداد األجــرة وعــدم بيــان تاريــخ محــدد لبــدء ســريان‬\n     ‫ا ال أثــر شــرعي يترتــب عليــه‪ .‬وبنــاء عليــه ‪،‬‬ ‫اإليجــار يجعلــه وعــد ًا باط ـ ً‬\n     ‫ا‬‫فإننــا نكــرر طلباتنــا الســابقة بــرد دعــوى املدعيــة جملــة وتفصي ـ ً‬\n     ‫واحلكــم بفســخ العقــد بــن موكلــي واملدعيــة‪ .‬وتفضلــوا بقبــول وافــر‬\n     ‫التحيــة والتقديــر) انتهــى نصــه ثــم جــرى رفــع اجللســة للدراســة والتأمــل‬\n     ‫ـاء‬\n     ‫ويف جلســة أخــرى حضــر الطرفــان ثــم جــرى قفــل بــاب املرافعــة فبنـ ً‬\n     ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ولكــون العقــد معلق ـ ًا علــى‬\n     ‫االســتالم وانتهــاء املؤجــر مــن بنــاء احملطــة وجتهيزها وعقــود املعاوضات‬\n     ‫ال يصــح تعليقهــا وألن اجلهــل بزمــان ابتــداء العقــد يــؤدي إلــى اجلهــل مبدته‬\n     ‫وهــذا يبطلــه قــال يف املغنــي جــ‪ 8‬صــ‪( : 13‬وإن اكتــرى فســطاط ًا إلــى‬\n     ‫مكــة ولــم يقــل متــى أخــرج فالكــراء فاســد وبــه قــال أبــو ثــور وهــو‬\n     ‫قيــاس قــول الشــافعي ‪ ،‬وقــال أصحــاب الرأي‪ :‬يجوز استحســان ًا بخالف‬\n     ‫القيــاس ‪ ،‬ولنــا‪ :‬أنهــا مــدة غيــر معلومــة االبتــداء فلــم يجــز ‪ ،‬كمــا لــو‬\n     ‫قــال‪ :‬أجرتــك داري مــن حــن يخــرج احلــاج إلــى آخــر الســنة ‪ )...‬أ‪.‬ه ـ وألن‬\n     ‫التعليــق علــى املجهــول شــرط باطــل مبطــل للعقــد كمــا قــال يف‬\n     ‫الكشــاف جــ‪ 3‬صــ‪( : 222‬النــوع الثالــث مــن الشــروط الفاســدة أن‬\n     ‫يشــترط البائــع شــرط ًا يعلــق البيــع عليــه كقولــه‪ :‬بعتــك إن جئتنــي‬\n\n\n‫‪77‬‬\n\f‫بكــذا أو بعتــك إن رضــي فــان ‪ )...‬أ‪.‬ه ـ والعقــد محــل النظــر هنــا يف‬\n‫حقيقتــه يشــتمل علــى تعليــق األجــل املفضــي إلــى تعليــق العقــد ولقولــه يف‬\n‫الشــرح املمتــع جــ‪ 10‬صــ‪( : 35‬فلــو أجــر ســيارة محركهــا معطــل للســفر‬\n‫عليهــا ‪ ،‬فــإن اإلجــارة ال تصــح ‪ ،‬وإذا قــال املســتأجر لصاحبهــا‪ :‬متــى‬\n‫أصلحتهــا فقــد اســتأجرتها منــك الشــهر بكــذا وكــذا ‪ ،‬فهنــا ال تصــح‬\n‫اإلجــارة أيض ـ ًا ؛ ملــا يلــي‪ :‬أوالً‪ :‬أن العقــود واملعاوضــات ال يصــح تعليقهــا‬\n‫كمــا هــو املذهــب‪ .‬ثاني ـاً‪ :‬أن هــذا مجهــول ‪ ،‬أي ابتــداء املــدة مــن‬\n‫التصليــح‪ ،‬والتصليــح غيــر معلــوم وعلــى هــذا فــا تصــح ‪ ،‬فــإذا كان‬\n‫فيهــا خــراب قليــل ونعلــم أنهــا تصلــح خــال يــوم أو يومــن فإنــه يجــوز‬\n‫تأجيرهــا) أ‪.‬ه ـ ولــكل مــا ذكــر ولغيــره فقــد ثبــت لــدي بطــان العقــد‬\n‫الــذي تعاقــد عليــه املتداعيــان أعــاه وصرفــت النظــر عــن دعــوى املدعــي‬\n‫لذلــك هــذا مــا ظهــر لــي وبــه حكمــت وجــرى نطقــه علن ـ ًا مبجلــس‬\n‫احلكــم الشــرعي الســاعة العاشــرة فقــرر املدعــى عليــه القناعــة ولــم‬\n‫يقنــع املدعــي واســتعد بتقــدمي الئحــة اعتراضيــة وجــرى تســليمه نســخة‬\n‫مــن احلكــم بنفــس اليــوم لتقــدمي مــا لديــه مــن اعتــراض وجــرى إفهامــه‬\n‫بتعليمــات االســتئناف وأن عليــه تقــدمي اعتراضــه يف مــدة أقصاها ثالثون‬\n‫يومـ ًا مــن تاريــخ هــذا اليــوم ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/30‬ه ـ احلمــد هلل‬\n‫وحــده‪ ،‬وبعــد‪ :‬قــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف‬\n‫مــزودة بقرارهــا رقــم ‪ 3446360‬يف ‪1434/02/25‬ه ـ املتضمــن بعــد‬\n‫املقدمة مانصه ( وبدراسة الصك وصورة ضبطه والالئحة االعتراضية‬\n‫وأوراق املعاملــة لوحــظ وجــود نقــص يف صــورة الضبــط ينبغــي إكمالــه‬\n‫فعلــى فضيلــة القاضــي مالحظــة مــا ذكــر وإكمــال مــا يلــزم نحــوه واهلل‬\n\n\n                                                                                         ‫‪78‬‬\n\f     ‫املوفــق) انتهــى نصــه والقــرار موقــع ومختــوم مــن أصحــاب الفضيلــة‬\n     ‫قاضــي اســتئناف ‪ .................‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n     ‫‪ ....................‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ...............‬ختمــه وتوقيعــه‬\n     ‫وعليــه‪ :‬أجيــب أصحــاب الفضيلــة بأنــه مت مالحظــة مــا ذكــر ومت‬\n     ‫ال‬\n     ‫إكمــال الــازم وتوجيــه املوظــف املختــص مبالحظــة ذلــك مســتقب ً‬\n     ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وسلم‪ .‬حرر يف ‪1434/03/14‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪ 1434/06/05‬ه ـ وقــد‬\n     ‫عــادت إلينــا املعاملــة مــن محكمــة االســتئناف مــزودة بالقــرار ذي الرقــم‬\n     ‫(‪ )34218870‬يف ‪1434/05/21‬ه ـ واملتضمــن بعــد املقدمــة مــا نصــه‬\n     ‫( وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n     ‫وأوراق املعاملة وباالطالع على ما أجاب به فضيلة القاضي على قرارنا‬\n     ‫ذي الرقــم (‪ )3446360‬وتاريــخ ‪1434/02/25‬ه ـ قررنــا املصادقــة علــى‬\n     ‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق) انتهــى نصــه والقــرار موقــع‬\n     ‫ومختــوم مــن قاضــي اســتئناف الشــيخ ‪ ................‬وقاضــي اســتئناف‬\n     ‫الشــيخ ‪ ................‬ورئيــس الدائــرة الشــيخ ‪ ......................‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                               ‫حــرر يف ‪1434/6/5‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪ 34709787‬وتاريــخ ‪1434/3/22‬ه ـ الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة القطيــف برقــم ‪34556656‬‬\n     ‫وتاريــخ ‪1434/3/17‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n\n\n‫‪79‬‬\n\f‫القاضــي باحملكمــة ً الشــيخ‪ ...................../‬املســجل برقــم ‪33476296‬‬\n‫وتاريــخ ‪1433/12/22‬ه ـ بشــأن دعوى‪/‬شــركة ‪.........................‬‬\n‫ضــد‪ ........................./‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق دراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي على قرارنــا ذي الرقــم ‪/3446360‬ق‪/2‬ب‬\n‫والتاريــخ ‪1434/2/25‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                   ‫حــرر يف‪1434/5/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪80‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":64,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"78f8a50dfccf176da93d60240b89ff5d6ca11df09686924f8b89548ee460395d","normalized_text_hash":"b6f8afb32f2d4f974fbb0b7329144978428ee2362260a457bb5d98c75b3f9bbe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p64-33476296"},{"id":"22c72399-9193-54c1-a630-d9dce750039a","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة « استثمار» -طلب إخاء عقار -مدة عقد إجارة مجهول -عدم االنتفاع من العن املؤجرة ألمر خارج عن إرادة طريف العقد -حكم بفسخ عقد إجارة -حكم بإعادة أجرة مسلمة- حكم بعدم استحقاق املدعى عليه االنتفاع بالعن املؤجرة بقية املدة الواردة يف العقد.","document_number":"3450435","case_number":"33442221","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/30","year":"1434","subject":"عقد -إجارة « استثمار» -طلب إخاء عقار -مدة عقد إجارة مجهول -عدم االنتفاع من العن املؤجرة ألمر خارج عن إرادة طريف العقد -حكم بفسخ عقد إجارة -حكم بإعادة أجرة مسلمة- حكم بعدم استحقاق املدعى عليه االنتفاع بالعن املؤجرة بقية املدة الواردة يف العقد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/2/30 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3450435 :‬‬\n                        ‫َر ْق ُم الدعوى‪33442221 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34208836‬تاريخه‪1434/5/7 :‬هـ‬\n\n\n\n     ‫عقــد‪ -‬إجــارة « اســتثمار» ‪ -‬طلــب إخــاء عقــار ‪ -‬مــدة عقــد إجــارة‬\n     ‫مجهــول ‪ -‬عــدم االنتفــاع مــن العــن املؤجــرة ألمــر خــارج عــن إرادة‬\n     ‫طــريف العقــد ‪ -‬حكــم بفســخ عقــد إجــارة ‪ -‬حكــم بإعــادة أجــرة ُمســلمة‪-‬‬\n     ‫حكــم بعــدم اســتحقاق املدعــى عليــه االنتفــاع بالعــن املؤجــرة بقيــة‬\n                                                         ‫املــدة الــواردة يف العقــد‪.‬‬\n\n\n\n\n                                 ‫‪ .1‬أن النبي صلى اهلل عليه وسلم نهى عن الغرر‬\n     ‫‪ .2‬قــال اخلرقــي ( فــان جــاء أمــر غالــب يحجــز املســتأجر عــن منفعــة مــا‬\n     ‫وقــع عليــه العقــد لزمــه مــن األجــر مبقــدار انتفاعــه )ا‪.‬ه ـ املغنــى ‪.27/8‬‬\n     ‫‪ .3‬وقــال ابــن قدامــه يف املغنــى ‪ ( 24/8‬اجمــع كل مــن نحفــظ عنــه مــن‬\n     ‫أهــل العلــم أن اســتئجار املنــازل جائــز وال يجــوز إجارتهــا إال علــى مــدة‬\n     ‫معلومــة ) وقــال (إذا أتلفــت العــن قبــل قبضهــا فــان اإلجــارة تنفســخ‬\n     ‫بغيــر خــاف نعلمــه الن املعقــود عليــه تلــف قبــل قبضــه) ا‪.‬ه ـ ‪.29/8‬‬\n     ‫وقــال ( أن يحــدث علــى العــن مــا مينــع نفعهــا فــإن لــم يبــق فيهــا نفــع‬\n     ‫ا فهــي كالتالفــة ســواء ألن املنفعــة التــي وقــع عليهــا العقــد تلفــت‬‫أصـ ً‬\n                                            ‫فانفســخت اإلجــارة ) املغنــى ح‪ 8‬صــ‪29‬‬\n\n\n\n\n‫‪81‬‬\n\f‫ادعــى املدعــي بالوكالــة ضــد املدعــى عليــه أن موكلــه اجـ ّـر علــى‬\n‫املدعــى عليــه جــزء مــن مزرعتــه املوصوفــة بالدعــوى مــدة أربــع عشــرة‬\n‫ســنة مــن ‪1430/1/1‬ه ـ علــى أن يدفــع أجــرة اخلمــس ســنوات األولــى‬\n‫وقدرهــا ثالثمائــة ألــف ريــال مــن كل ســنة تدفــع مقدم ـ ًا واخلمــس‬\n‫ســنوات الثانيــة بواقــع أربعمائــة ألــف ريــال عــن كل ســنة واألربــع‬\n‫ســنوات األخيــرة بواقــع خمســمائة ألــف ريــال عــن كل ســنة علــى أن‬\n‫يلتــزم املدعــى عليــه بإنشــاء احملــل باخلرســانة املســلحة والهنجــر وقــد‬\n‫اســتلم املدعــى عليــه العــن املؤجــرة ومت اســتالم أجــرة الســنة األولــى‬\n‫مبلغ ـ ًا وقــدره ثالثمائــة ألــف ريــال ولكــن املدعــى عليــه لــم يقــم بإنشــاء‬\n‫اخلرســانة ولــم يســلم أجــرة الســنة الثانيــة وال الثالثــة وال الرابعــة ويوجــد‬\n‫شــرط يف العقــد انــه يف حــال انقضــاء ســتة أشــهر دون دفــع االســتحقاق‬\n‫فيحــق للمدعــي فســخ العقــد وطلــب املدعــي احلكــم علــى املدعــى عليــه‬\n‫بإخــاء العــن املؤجــرة وتســليمه للمدعــي أصالــة‪ ،‬أجــاب املدعــى عليــه‬\n‫باملصادقــة علــى عقــد اإلجــارة وقــرر أن العــن املؤجــرة جــزء مــن مزرعــة‬\n‫املدعــي واملدعــي لــم يقــم بتســليمه أوراقــا الزمــة مــن اجــل إنهــاء بعــض‬\n‫اإلجــراءات لــدى األمانــة مــن اجــل قــرار املزرعــة واســتخراج رخصة وقرر‬\n‫املدعــى عليــه انــه لــم يتمكــن مــن االســتفادة مــن العــن املؤجــرة ولــم‬\n‫يتمكــن منهــا ألمــر خــارج عــن إرادتــه وانــه غيــر ملــزم بتســليم األجــرة‬\n‫ومــع ذلــك قــرر انــه راجــع األمانــة وأنهــى بعــض اإلجــراءات ولــم يبــق ســوى‬\n‫عمــل قــرار للمزرعــة مــن املكتــب الهندســي وانــه تفاجــأ بهــذه الدعــوى‬\n‫وانــه متمســك بالعقــد ومســتعد بتســليم األجــرة مــن تاريــخ اســتالم صــك‬\n\n                                                                                       ‫‪82‬‬\n\f     ‫القطعتــن مــن كاتــب العــدل‪ ،‬مت اطــاع ناظــر القضيــة علــى العقــد بــن‬\n     ‫الطرفني‪،‬تصــادق الطرفــان علــى انــه لــم يتــم اســتخراج رخصــة علــى‬\n     ‫املوقــع إلــى تاريــخ إقامــة الدعــوى وان ذلــك ألمــر خــارج عــن إرادتهمــا‬\n     ‫ـاء‬\n     ‫وانــه لــم تتــم االســتفادة مــن العــن املؤجــرة ‪ ،‬قــرر ناظــر القضيــة انــه بنـ ً‬\n     ‫علــى أن مــدة إخــراج الرخصــة مجهولــة فتكــون بدايــة العقــد مجهولــة‬\n     ‫وان الطرفــن تصادقــا علــى أن عــدم إخــراج الرخصــة ألمــر خــارج عــن‬\n     ‫إرادتهمــا والن النبــي صلــى اهلل عليــه وســلم نهــى عــن الغــرر وقــرر‬\n     ‫الفقهــاء انــه ال يجــوز تأجيــر العقــار إال علــى مــدة معلومــة فقــد صــدر‬\n     ‫احلكــم بفســخ عقــد اإلجــارة وإعــادة األجــرة إلــى املدعــى عليــه التــي‬\n     ‫ســلمها للمدعــي وقدرهــا ثالثمائــة ألــف ريــال وعــدم اســتحقاق املدعــى‬\n     ‫عليــه بقيــة املــدة الــواردة بالعقــد وتســليم املوقــع حــا ًال للمدعــي أصالــة ‪،‬‬\n     ‫قــرر الطرفــان عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف باملدينــة‬\n     ‫املنــورة باملوافقــة علــى احلكم‪،‬حضــر املدعــي وكالــة وقــرر انــه اســتلم‬\n     ‫املوقــع املؤجــر وســلم لوكيــل املدعــى عليــه مبلــغ األجــرة حســب منطــوق‬\n                                                                                 ‫احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ......... /‬القاضــي يف احملكمــة العامــة‬\n     ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة باملدينــة املنورة‪/‬املســاعد برقــم ‪ 33442221‬وتاريــخ‬\n     ‫‪1433/07/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331246810‬وتاريــخ‬\n     ‫‪1433/07/02‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/07/26‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 11 : 00‬وفيها حضر‪ ......... /‬ســعودي اجلنســية مبوجب‬\n\n‫‪83‬‬\n\f‫الهويــة الوطنيــة رقــم ‪ .........‬الوكيل الشــرعي عن‪ ......... ......... /‬مبوجب‬\n‫الوكالــة اخلاصــة الصــادرة مــن كاتــب عــدل املدينــة الثانيــة برقــم ‪.........‬‬\n‫وتاريــخ ‪1433/7/1‬ه ـ و ادعــى علــى احلاضــر معــه يف مجلــس‬\n‫احلكــم‪ ........./‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ...‬بقولــه‬\n‫‪ :‬إن موكلي أجر املدعى عليه جزء من مزرعته الواقعة يف طريق‪.........‬‬\n‫مســاحته ‪ :‬ألفــان و مائــة و ســبعون متــر ًا مربعـ ًا و هــو املربــع رقــم واحــد‬\n‫و املربــع رقــم أثنــن الواقعــن علــى الشــارع املذكــور مــدة أربعــة عشــر‬\n‫ـدء مــن ‪1430/1/1‬ه ـ إلــى ‪1443/12/30‬ه ـ علــى ان تدفــع‬                ‫عام ـ ًا أبتـ ً‬\n‫االجــرة علــى النحــو التالــي ‪ :‬اخلمــس ســنوات االولــى بواقــع ثالثمائــة ألــف‬\n‫ريــال عــن كل ســنة تدفــع مقدم ـ ًا و اخلمــس ســنوات الثانيــة بواقــع‬\n‫أربعمائــة ألــف ريــال عــن كل ســنة تدفــع مقدمـ ًا واألربــع ســنوات املتبقيــة‬\n‫بواقــع خمســمائة ألــف ريــال عــن كل ســنة تدفــع مقدمـ ًا علــى ان يلتــزم‬\n‫الطــرف الثانــي بإنشــاء احملــل باخلرســانة املســلحة والهنقــر وقــد أســتلم‬\n‫املدعــى عليــه احملــل بالتاريــخ املذكــور و اســتلمنا منــه اجــرة الســنة‬\n‫االولــى تدفــع مقدمـ ًا و لكنــه لــم يقــم بإنشــاء شــيء علــى املوقــع و دخلــت‬\n‫عليــه الســنة الثانيــة إعتبــار ًا مــن ‪1431/1/1‬ه ـ ولــم يدفــع مــن أجرتهــا‬\n‫شــيء كمــا دخلــت عليــه الســنة الثالثــة يف ‪1432/1/1‬ه ـ و لــم يدفــع من‬\n‫اجرتهــا شــيئ ًا كمــا دخلــت عليــه اجرة الســنة الرابعة مــن ‪1433/1/1‬هـ‬\n‫ولــم يدفــع مــن أجرتهــا شــيئ ًا و قــد أشــترطنا عليــه يف العقــد أنــه يف حــال‬\n‫إنقضــاء ســتة أشــهر مــن بدايــة العــام دون دفــع اإلســتحقاق فيحــق لنــا‬\n‫فســخ العقــد تلقائيـ ًا و نهائيـ ًا و حيــث احلــال ما ذكــر فإننا نطلب احلكم‬\n‫علــى املدعــى عليــه بإخــاء املوقــع حــا ًال و تســليمه لنــا هكــذا قــرر‬\n‫دعــواه ‪ .‬و بعــرض ذلــك علــى املدعــى عليــه صــادق علــى إســتئجاره املوقــع‬\n\n\n                                                                                          ‫‪84‬‬\n\f     ‫املذكــور إعتبــار ًا مــن التاريــخ املذكــور إال انــه قــال إن األرض املؤجــرة‬\n     ‫جــزء مــن مزرعــة و لــم يســلمني املدعــي أصالــه االوراق الالزمــه مــن أجــل‬\n     ‫قــرار ذرعــه و مــن ثــم تطبيقهــا و مــن ثــم إســتخراج الرخصــة و لذلــك فلــم‬\n     ‫امتكــن مــن اإلســتفادة مــن العــن املؤجــرة و مــا دمــت لــم أمتكــن مــن‬\n     ‫العــن املؤجــرة بأمــر خــارج عــن إرادتــي فأنــا غيــر ملــزم بدفــع شــيء مــن‬\n     ‫األجــرة و مــع ذلــك فقــد قمــت مبراجعــة االمانــة بالعقــد فقــط مــع انهــم‬\n     ‫لــم يوكلونــي بإســتخراج رخصــة وال قــرار ذرعــة و مــع ذلــك فقــد راجعــت‬\n     ‫األمانــه حتــى مت إعتمــاد املخطــط يف تاريــخ ‪1433/6/3‬ه ـ و لــم يبــق‬\n     ‫عليهــا إال عمــل قــرار الــذرع مــن املكتــب الهندســي ثــم لإلمانــة ثــم‬\n     ‫لكاتــب العــدل و لكنــي تفاجــأت برفــع هذه الدعوى يف ‪1433/7/2‬هـ‬\n     ‫أي بعــد حوالــي شــهر واحــد فقــط و انــا متمســك بالعقــد و لكننــي‬\n     ‫مســتعد باالجــره مــن تاريــخ اســتالم صــك القطعتــن واحــد و أثنــن مــن‬\n     ‫كاتــب العــدل هكــذا أجــاب ‪ .‬و بعــرض ذلــك علــى املدعــي وكالــه‬\n     ‫وســؤاله هــل ســلمتم املدعــى عليــه صاحلــه لإلســتعمال او هــل أشــترطتم‬\n     ‫عليــه القيــام بذلــك فقــال‪ :‬إن العقــد يلزمــه بأســتخراج جميــع مــا يلــزم‬\n     ‫لألجــرة هكــذا أجــاب فجــرى ســؤاله عــن أي فقــرة يف العقــد تلزمــه‬\n     ‫ذلــك فقــال فلــم يدلنــا علــى فقــرة معينــه إال انــه قــال إننــا لــم مننعــه مــن أي‬\n     ‫شــيء هكــذا اجــاب فطلبــت مــن الطرفــن إحضــار العقــد فأســتعدا‬\n     ‫بإحضــاره لرصــده و مناقشــته يف اجللســه القادمــة ‪ .‬و يف يــوم الثالثــاء‬\n     ‫املوافــق‪ 1433/09/12‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان‬\n     ‫وجــرى ســؤال املدعــي عــن الغــرض مــن تأجيــر املوقــع علــى املدعــى عليــه‬\n     ‫فقــال مــن اجــل أن نســتثمرها يف بنــاء معــارض أو صــاالت جتاريــة فجــرى‬\n     ‫ســؤاله عمــا ذكــره املدعــى عليــه مــن عــدم متكنــه مــن اســتخراج‬\n\n\n‫‪85‬‬\n\f‫الرخصــه ومــا يلزمهــا إلــى تاريخــه وهــل هــو بســبب منــه او بأمــر خــارج‬\n‫عــن إرادتــه فقــال إنــه ألجــل أمــر خــارج عــن إرادتنــا جميعــا هكــذا أجاب‬\n‫هــذا وقــد جــرى ســؤال املدعــي عمــا ذكــره مــن أن املدعــى عليــه ملــزم‬\n‫بإخــراج الرخصــه بحســب العقــد فابــرز العقــد بــن كل مــن الطــرف‬\n‫االول‪ .........‬و‪ .........‬والطــرف الثانــي ‪ .........‬مبــا أن الطــرف االول ميلــك‬\n‫كامــل العقــار الواقــع طريــق‪ .........‬قطعــه رقــم ‪ 1‬و ‪ 2‬ومســاحتهما ألفــان‬\n‫ومائــة وســبعون متــرا بالصــك رقــم ‪ 3/4/170‬يف ‪1425/3/13‬هـ ويوجد‬\n‫رغبــه لــدى الطــرف الثانــي يف اســتثمارها وأتفــق الطرفــان علــى مــا يلــي‬\n‫أوال ‪ :‬مــدة االجــار أربــع عشــرة ســنة هجريــة ابتــداء مــن ‪1430/01/01‬هـ‬\n‫الــى ‪ 1443/12/30‬ه ـ ‪ .‬ثانيــا ‪ :‬يعطــى الطــرف األول للطــرف الثانــي‬\n‫ســنة هجريــة مهلــة للبنــاء تبــدأ مــن ‪1429/01/01‬ه ـ وتنتهــي يف‬\n‫‪ 1429/12/30‬ه ـ بــدون مقابــل علــى أن تدفــع كامــل قيمــة الســنة‬\n‫االيجاريــة لعــام ‪1430‬ه ـ عنــد توقيــع العقــد ‪ .‬ثالثــا‪ :‬أتفــق الطرفــان علــى‬\n‫توزيــع اإلجــرة للســنوات املذكــورة ( كمــا ذكــر يف الدعــوى) ‪ .‬رابعــا ‪:‬‬\n‫يلتــزم الطــرف الثانــي بإنشــاء العقــار محــل االتفــاق باخلرســانه املســلحة‬\n‫والهنقــر ‪ .‬خامســا ‪ :‬للطــرف الثانــي احلــق بالتأجيــر بالباطــن كل أو جــزء‬\n‫هــذا مــن العقــار ملــدة ال تتجــاوز مــدة العقــد وال يترتــب علــى ذلــك ضــرر‬\n‫للعــن املؤجــرة ‪ .‬سادســا ‪ :‬يلتــزم الطــرف الثانــي بســداد االيجــار يف‬\n‫الوقــت احملــدد ـ ســابعا ‪ :‬يف حالــة انقضــاء ســتة اشــهر مــن بدايــة العــام‬\n‫الهجــري دون دفــع االســتحقاق يحــق للطــرف االول فســخ العقــد تلقائيــا‬\n‫وتعــود ملكيــة االنقــاض للطــرف االول مــع حتمل الطــرف الثاني كامل‬\n‫املســؤولية واملعنويــة املترتبــة علــى ذلــك للطــرف االول ثامنــا‪ :‬بعــد انتهــاء‬\n‫مــدة العقــد كامــل املشــروع للطــرف االول علــى أن يكــون صاحلــا‬\n\n\n                                                                                       ‫‪86‬‬\n\f     ‫لألســتعمال ‪ .‬تاســعا ‪ :‬جميع عقود املس ــتأجرين للطرف األول ‪ .‬عاشــرا‪:‬‬\n     ‫يف حالــة رغبــة الطــرف االول بيــع العقــار محــل العقــد فعليــه إفهــام‬\n     ‫املشــتري بــأن يحــل محلــه عــي اإللتــزام يف هــذا العقــد وبنــوده أنتهــى‬\n     ‫وبســؤال املدعــي مــا دام أن عــدم إخــراج الرخصــة الــى تاريخــه ألمــر‬\n     ‫خــارج عــن إرادة الطرفــن فمــا وجــه االســتدالل بالعقــد علــى إلزامــه‬\n     ‫باإلخــاء فقــال إن عــدم متكنــه مــن ذلــك نتــج عنــه عــدم ســداد األجــرة‬\n     ‫وعــدم متكــن موكلــي مــن بيعهــا أو االســتفاده منهــا هكــذا أجــاب‬\n     ‫فجــرى ســؤال املدعــى عليــه عمــا مت الوصــول إليــه يف اخــراج الرخصــة‬\n     ‫فقــال إن املوقــع مت تخطيطــه مــن قبــل املكتــب الهندســي كمــا مت‬\n     ‫اعتمــاد املخطــط مــن االمانــة ومــن ثــم ســيتم بعثــه الــى كاتــب عــدل‬\n     ‫الســتخراج الصكــوك ومــن ثــم ســتعود الــى االمانــة الخــراج الرخصــة‬\n     ‫وال أعلــم كــم مــن الوقــت تســتغرق ولكننــي خســرت مــن اجــل هــذا‬\n     ‫املوقــع وبعــت عقــارا مبليــون ومئتــي ألــف ريــال مــن أجــل اســتثمارها يف‬\n     ‫املوقــع كمــا أننــي ال زلــت اراجــع االمانــة مــن أجلهــا مبجــرد العقــد ولــم‬\n     ‫يوكلونــي وأطالبهــم بإعطائــي وكالــه حتــى أمتكــن مــن اختصــار‬\n     ‫الوقــت بهــا هكــذا اجــاب وبعرضــه علــى املدعــي رفــض اعطــاءه‬\n     ‫وكالــه وقــال إن لنــا اربعــة مندوبــن يف االمانــة يتابعونهــا ولنــا بقيــة‬\n     ‫القطــع اخلمــس نتابعهــا ونطلــب فســخ العقــد هكــذا أجــاب ورفعــت‬\n     ‫اجللســة للتأمل واصدار احلكم ‪ .‬و يف يوم الســبت املوافق ‪1434/2/30‬‬\n     ‫أفتتحــت اجللســه و فيهــا حضــر املدعــي وكالة كما حضــر املدعو‪.........‬‬\n     ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .........‬الوكيــل الشــرعي‬\n     ‫عــن‪ .........‬مبوجــب الوكالــة اخلاصــة الصــادرة مــن كاتــب عــدل املدينــة‬\n     ‫الثانيــة برقــم ‪ .........‬وتاريــخ ‪1431/5/24‬ه ـ جلــد ‪ 6310‬و املخــول فيهــا‬\n\n\n‫‪87‬‬\n\f‫باملرافعــة و املدافعــة و اإلقــرار و اإلنــكار و الصلــح و التنــازل و اإلســتالم‬\n‫و التســليم ‪ ..‬الــخ و جــرى ســؤال الطرفــن عــن رخصــة اإلنشــاء و قــرر‬\n‫املدعــى عليــه وكالــة بــأن موكلــه ال يســتطيع إســتخراج الرخصــة حيث‬\n‫إن املخطــط بكامــل املوقــع صــدر عليــه أمــر إختــزال و بذلــك فــا ميكن‬\n‫إخــراج الرخصــة مــن قبــل موكلــي لكونــه غيــر مالــك وال وكيــل عــن‬\n‫املالــك هكــذا قــرر كمــا قــرر املدعــى عليــه بانه لم يتم إخــراج الرخصة‬\n‫إلــى تاريخــه هكــذا قــرر‪ ،‬فجــرى ســؤال الطرفــن عمــا ذكــر يف‬\n‫الدعــوى مــن القطعــة رقــم واحــد و القطعــة رقــم أثنــن فقــرر الطرفــان‬\n‫بــأن القطعتــن همــا اللتــان أجرتــا علــى املدعــى عليــه إلســتثمارها‬\n‫ولكــن لــم تتــم إخــراج الرخصــة عليهمــا بســبب وجــود قطــع أخــرى‬\n‫مملوكــة للمدعــن فيهــا تداخــل مــع اجلــوار هكــذا قــررا ‪ .‬فجــرى‬\n‫عــرض الصلــح علــى الطرفــن فلــم نتمكــن مــن ذلــك و طلــب الطرفــان‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة‬   ‫إصــدار احلكــم الــازم ‪ .‬فبنـ ً‬\n‫ومصادقــة الطرفــان علــى العقــد املذكــور و حيــث صــادق الطرفــان‬\n‫علــى عــدم إخــراج الرخصــة إلــى تاريخــه و حيــث صــادق الطرفــان علــى‬\n‫عــدم أســتفادة املدعــى عليــه مــن العــن املؤجــرة وحيــث إن مــدة إخــراج‬\n‫الرخصــة مجهولــة وغيــر معلومــة وبذلــك فــإن بدايــة مــدة العقــد مجهولــة‬\n‫كمــا صــادق الطرفــان علــى أن عــدم إخــراج الرخصــة ألمــر خــارج عــن‬\n‫إرادتهمــا وحيــث مضــي علــى العقــد قرابــة أربــع ســنوات ولــم يتــم إخــراج‬\n‫الرخصــة إلــى تاريخــه وال االســتفادة مــن املوقــع إلــى تاريخــه وألن النبــي‬\n‫صلــى اهلل عليــه و ســلم‪ :‬نهــى عــن الغــرر وحيــث قــرر الفقهــاء انــه ال يجــوز‬\n‫تأجيــر العقــار إال علــى مــدة معينــه معلومــة قــال اخلرقــي ‪( :‬فــإن جــاء أمــر‬\n‫غالــب يحجــز املســتأجر عــن منفعــة مــا وقــع عليــه العقــد لزمــه مــن االجــر‬\n\n\n                                                                                        ‫‪88‬‬\n\f     ‫مبقــدار مــدة إنتفاعــه) أ‪ .‬هــ‪ ،‬املغنــي ج ‪ 8‬ص ‪ 27‬و قــال إبــن قدامــه‪:‬‬\n     ‫(أجمــع كل مــن نحفــظ عنــه مــن أهــل العلــم أن اســتئجار املنــازل جائــز‬\n     ‫وال جتــوز إجارتهــا إال علــى مــدة معينــه معلومــه) أ‪.‬ه ـ املغنــي ج ‪ 8‬ص ‪24‬‬\n     ‫و قــال‪( :‬إذا تلفــت العــن قبــل قبضهــا فــإن اإلجــارة تنفســخ بغيــر خــاف‬\n     ‫نعلمــه الن املعقــود عليــه تلــف قبــل قبضــه) أ‪ .‬ه ـ املغنــي ج ‪ 8‬ص ‪،28‬‬\n     ‫وقــال يف موضــع اخــر‪( :‬أن يحــدث علــى العــن مــا مينــع نفعهــا فــإن لــم يبــق‬\n     ‫ا فهــي كالتالفــة ســواء ألن املنفعــة التــي وقــع عليهــا‬      ‫فيهــا نفــع أص ـ ً‬\n     ‫العقد تلفت فإنفسخت اإلجارة) أ‪ .‬هـ املغني ج ‪ 8‬ص ‪ . 29‬فقد أصدرت‬\n     ‫اآلتــي‪ :‬أوالً‪ :‬حكمــت بفســخ عقــد اإليجــار املذكــور بــن الطرفــن ‪.‬‬\n     ‫ثانيـاً‪ :‬حكمــت علــى املدعــي بإعــادة الدفعــة التــي أســتلمها مــن املدعــى‬\n     ‫عليــه و قدرهــا ثالثمائــة ألــف ريــال ‪ .‬ثالث ـاً‪ :‬حكمــت بعــدم أســتحقاق‬\n     ‫املدعــى عليــه اإلنتفــاع باملوقــع بقيــة املــدة الــواردة يف العقــد ‪ .‬رابع ـاً‪:‬‬\n     ‫حكمــت بتســليم املوقــع ملــوكل املدعــي حــا ًال هــذا مــا حكمــت بــه‬\n     ‫فليعلــم و بعرضــه علــى الطرفــن قــررا جميع ـ ًا عــدم القناعــة و قــررت‬\n     ‫تســليم كل منهمــا صــورة مــن صــك احلكــم لتقــدمي األئحــة اإلعتراضيــة‬\n     ‫حســب املتبــع و بــاهلل التوفيــق و صلــى اهلل علــى ســيدنا محمــد و علــى آلــه‬\n                                          ‫وصحبه و سلم حرر بتاريخ ‪1434/2/30‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫بخطابهــا رقــم ‪ 331246810‬يف ‪1434/5/25‬ه ـ وبرفقهــا القــرار رقــم‬\n     ‫‪ 34208836‬يف ‪1434/5/7‬ه ـ املتضمــن وبدارســة الصــك وصــورة‬\n     ‫ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم وعلــى‬\n     ‫فضيلتــه مراعــات التنبيــه املرفــق باملعاملــه ‪ .‬قاضــي اســتئناف ‪.........‬‬\n     ‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ .........‬موقــع يف االصــل وموافــق علــى‬\n\n\n‫‪89‬‬\n\f‫احلكــم ومنتــدب رئيــس الدائــرة ‪ .........‬ختمــه وتوقيعــه أ‪.‬ه ـ حتــى ال‬\n‫يخفــى جــرى حتريــره يف ‪1434/6/5‬ه ـ وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n                                  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنني املوافــق ‪1434/08/01‬هـ حضر‬\n‫‪ .........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪102571864‬الوكيــل‬\n‫الشــرعي عــن ‪ .........‬مبوجــب الوكالــه الصــادرة مــن املدينــة برقــم ‪.........‬‬\n‫يف ‪ 1433/07/01‬ه ـ وقــرر أن موكلــه أســتلم املوقــع كمــا أحضــر‬\n‫الشــيك رقــم رقــم ‪ .........‬يف ‪ 1434/08/1‬ه ـ املســحوب علــى مصــرف‬\n‫‪ ...‬مببلــغ وقــدره ثالثمائــة ألــف ريــال كمــا حضــر معــه ‪ .........‬ســعودي‬\n‫مبوجب الســجل املدني رقم ‪ .........‬الوكيل الشــرعي عن ‪ .........‬مبوجب‬\n‫الوكالــة الصــادرة مــن املدينــة برقــم ‪ .........‬يف ‪ 1434/07/24‬ه ـ والتــي‬\n‫تخــول لــه االســتالم وقــد جــرى تســليم الشــيك املذكــور ملــوكل املدعــى‬\n‫عليــه لــذا جــرى إثباتــه وبذلــك تكــون القضيــة منتهيــة وصلــى اهلل وســلم‬\n                                  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى منــا‬\n‫االطــاع نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ‪/‬د‪ ..........‬القاضــي باحملكمــة العامــة باملدينــة املنــورة واملســجل‬\n‫بعدد‪3450435‬وتاريخ‪1434/2/30‬ه ـ املتضمــن دعــوى ‪ .........‬ضــد‬\n‫‪ .........‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم وعلــى فضيلتــه‬\n‫مراعــات التنبيــه املرفــق باملعاملــة وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                              ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                       ‫‪90‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":81,"source_page_end":90,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1dac13677049d4697edb7502f5a28835b9189c8f7a73fb718c274062b5c48a59","normalized_text_hash":"a13ab7b13f0d68581f6f5e528bf3976b802f2678b98f9afc5d4016bdcd1852c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p81-3450435"},{"id":"60966baf-c243-563d-8a35-7cdd34b4c0a9","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -انتقال اإلجارة إلى املالك اجلديد ولزوم العقد فيها -إخاء عقار ورفع اليد عن العقار -وجوب الوفاء بالعقود - احلكم بلزوم عقد اإلجارة -ثبوت صحة عقد اإلجارة -صرف نظر عن دعوى طلب رفع يد املستأجر عن العقار -حكم بإخاء عقار بعد نهاية العقد -وجوب الوفاء بالعقود.","document_number":"33452634","case_number":"33591344","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة االحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/13","year":"1434","subject":"عقد -إجارة -انتقال اإلجارة إلى املالك اجلديد ولزوم العقد فيها -إخاء عقار ورفع اليد عن العقار -وجوب الوفاء بالعقود - احلكم بلزوم عقد اإلجارة -ثبوت صحة عقد اإلجارة -صرف نظر عن دعوى طلب رفع يد املستأجر عن العقار -حكم بإخاء عقار بعد نهاية العقد -وجوب الوفاء بالعقود.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪ 1433/11/13 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33452634 :‬‬\n                          ‫َر ْق ُم الدعوى‪33591344 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34384314‬تاريخه‪1434/12/23 :‬هـ‬\n\n\n       ‫عقــد ‪ -‬إجــارة ‪ -‬انتقــال اإلجــارة إلــى املالــك اجلديــد ولــزوم العقــد‬\n       ‫فيهــا ‪ -‬إخــاء عقــار ورفــع اليــد عــن العقــار ‪ -‬وجــوب الوفــاء بالعقــود ‪-‬‬\n       ‫احلكــم بلــزوم عقــد اإلجــارة ‪ -‬ثبــوت صحــة عقــد اإلجــارة ‪ -‬صــرف نظــر‬\n       ‫عــن دعــوى طلــب رفــع يــد املســتأجر عــن العقــار ‪ -‬حكــم بإخــاء عقــار‬\n                                   ‫بعــد نهايــة العقــد ‪ -‬وجــوب الوفــاء بالعقــود‪.‬‬\n\n\n\n\n                              ‫‪ -1‬قوله تعالى «يا أيها الذين آمنوا أوفوا بالعقود»‬\n                      ‫‪ -2‬قوله صلى اهلل علية وسلم «املسلمون على شروطهم»‬\n       ‫‪ -3‬قــال بــن رجــب «يف القاعــدة السادســة والثالثــن مــن قواعــده بعــد‬\n       ‫كالم طويــل والقســم الثانــي أن تكــون إجارتــه مبلكــه ثــم تنتقــل إلــى‬\n       ‫غيــره وهــو أنــواع وقــال يف ثانيهمــا أن ينتقــل امللــك إلــى مــن خلفــه يف‬\n       ‫مالــه ويقــوم مقامــه ويتلقــى امللــك عنــه فــا اعتــراض لــه علــى عقــوده‬\n                                ‫بــل هــو منفــذ لهــا وذلــك كالــوارث واملشــتري»‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــى ضــد وكيــل احــد البنــوك بأنــه اشــتري قطعــة ارض مت‬\n       ‫وصفها من مالكها بتاريخ ‪ 1427/8/3‬وكان البائع مالكها الســابق‬\n       ‫قــد اجــر األرض قبــل بيعهــا علــى البنــك املدعــى عليــه وان العقــد ينتهــي‬\n\n‫‪91‬‬\n\f‫يف ‪2012/8/1‬م وان املدعــى أخطــر البنــك قبــل انتهــاء العقــد بخطــاب‬\n‫مــؤرخ يف ‪2012/7/4‬م بانتهــاء العقــد الســابق ورغــب يف املفاوضــة حــول‬\n‫جتديــد العقــد إال أن البنــك رفــض ولــذا فقــد طالــب املدعــى إلــزام البنــك‬\n‫برفــع يــده مــن األرض ‪ ،‬أجــاب وكيــل البنــك باملصادقــة علــى الدعــوى‬\n‫ولكــن يــد البنــك علــى أألرض صحيحــة مبوجــب عقــد إيجــار مــع املالــك‬\n‫الســابق ومــن ضمــن شــروط فســخ العقــد البــد أن يكــون مكتوبــا وقبــل‬\n‫ســنة مــن تاريــخ نهايــة العقــد وقــرر وكيــل البنــك أن العقــد يعتبــر ســاري‬\n‫املفعــول والعقــد جتــدد خمــس ســنوات مــدة مماثلــة للعقــد األول ‪ ،‬أجــاب‬\n‫املدعــى بعــدم علمــه بالشــرط املشــار إليــه يف العقد بــن الطرفني‪،‬صادق‬\n‫املدعــى علــى العقــد الــذي ابرمــه املالــك الســابق مــع البنك املدعــى عليه‪،‬‬\n‫قــرر ناظــر القضيــة انــه بنــاء علــى الدعــوى واإلجابــة وبنــاء علــى الشــرط‬\n‫املــدون يف العقــد وألن األصــل يف العقــد الصحــة وملــا جــاء يف أســباب‬\n‫احلكــم ولقولــه تعالــى ((يــا أيهــا الذيــن امنــوا أوفــوا بالعقــود)) فقد صدر‬\n‫احلكــم بثبــوت صحــة عقــد البنــك املدعــي عليــه مــع املــدى ملــدة خمــس‬\n‫ســنوات ميالديــة مــن تاريــخ ‪2012/8/1‬م وصــرف النظــر عــن دعــوى‬\n‫املدعــى وإفهــام البنــك املدعــى عليــه باخلــروج مــن العقــار محــل الدعــوى‬\n‫عنــد نهايــة املــدة مــا لــم يكــن هنــاك عقــد جديــد‪ ،‬قــرر وكيــل البنــك‬\n‫القناعــة باحلكــم وقــرر املدعــى عــدم القناعــة ‪ .‬صــدر قــرار محكمــة‬\n                                        ‫االســتئناف باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                     ‫‪92‬‬\n\f     ‫العامــة‬\n         ‫ّ‬    ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة‬\n     ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة مبحافظــة االحســاء برقــم ‪ 33591344‬وتاريــخ ‪1433/10/09‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 331770322‬وتاريــخ ‪1433/10/09‬ه ـ‬\n     ‫حضــر‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬وحضــر‬\n     ‫‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬الوكيــل‬\n     ‫عــن ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...‬و‪ ...‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬و‪ ...‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل الدنــي رقــم ‪ .......‬و‪ .......‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم ‪ .......‬و‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ .......‬و ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n     ‫و‪ .......‬بريطانــي اجلنســية مبوجــب اإلقامــة رقــم ‪ .......‬و ‪ .......‬بريطانــي‬\n     ‫اجلنســية مبوجــب اإلقامــة رقــم ‪ .......‬وبريطانــي اجلنســية مبوجــب اإلقامــة‬\n     ‫رقــم ‪ .......‬و ‪ .......‬بريطانــي اجلنســية مبوجــب جــواز الســفر رقــم ‪.......‬‬\n     ‫وبصفتهــم أعضــاء مجلــس إدارة ‪ ...‬كمــا هــو ثابــت بالســجل التجــاري‬\n     ‫الصــادر مــن وزارة التجــارة برقــم ‪ .......‬ومبوجــب الصالحيــات املخولــة‬\n     ‫ملجلــس اإلدارة واملذكــورة باملــادة ‪ 20‬مــن عقــد التأســيس والنظــام‬\n     ‫األساســي بالوكالــة الصــادرة مــن كاتــب العــدل املكلــف يف وزارة‬\n     ‫التجــارة والصناعــة برقــم ‪ 250‬يف تاريــخ ‪1432/1/8‬ه ـ واملخــول لــه فيهــا‬\n     ‫باملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوي والتســليم واالســتالم‬\n     ‫واإلقــرار وبســؤال املدعــي عــن دعــواه أجــاب بقولــه‪ :‬إننــي قــد اشــتريت‬\n\n‫‪93‬‬\n\f‫قطعــة األرض رقــم ‪ 34‬الواقعــة جنــوب ‪ .......‬مــن مخطــط رقــم ‪ 375‬مــن‬\n‫مالكهــا بتاريــخ ‪1427/8/3‬ه ـ مبوجــب الصــك الصــادر مــن كتابــة‬\n‫عــدل األحســاء األولــى برقــم ‪ 3/1/2407‬يف ‪1427/8/3‬ه ـ وقــد كان‬\n‫املالــك الســابق قــد أجــر األرض قبــل شــرائي لهــا علــى املدعــى عليهــا‬\n‫البنــك ‪ ...‬وقــد ألزمــت بهــذا العقــد وهــو ينتهــي بتاريــخ ‪2012/8/1‬م‬\n‫وقــد أخطــرت البنــك قبــل انتهــاء العقــد بخطــاب مــؤرخ يف ‪2012/7/4‬م‬\n‫بانتهــاء العقــد الســابق ورغبتــي يف مفاوضتــي شــخصيا حــول جتديــد‬\n‫العقــد إال أنهــم رفضــوا ذلــك لــذا فإننــي أطلــب إلــزام املدعــى عليهــا برفــع‬\n‫يدهــا عــن األرض هــذه دعــواي وبعــرض ذلــك علــى وكيــل املدعــى عليهــا‬\n‫أجــاب بقولــه‪ :‬مــا جــاء يف دعــوى املدعــي مــن شــراء األرض واســتئجارنا‬\n‫لهــا مــن قبــل املالــك الســابق فهــو صحيــح وموكلتــي ال تصــادق علــى‬\n‫طلــب املدعــي لكــون أن العقــد الــذي أبرمنــاه مــع املالــك الســابق مــن‬\n‫تاريــخ ‪1992/8/1‬م ومــا حلقــه مــن ملحقــات وكان آخرهــا امللحــق‬\n‫املــؤرخ يف ‪1427/12/14‬ه ـ مــن متديــد العقــد خمــس ســنوات يبــدأ‬\n‫مــن تاريــخ ‪2007/8/1‬م وقــد نــص يف العقــد علــى جتــدده تلقائيــا ملــدة‬\n‫مماثلــة مــا لــم يقــم أحــد الطرفــن بإخطــار الطــرف اآلخــر خطيــا خــاف‬\n‫ذلــك قبــل ســنة مــن تاريــخ انتهــاء العقــد فيكــون العقــد ســاري املفعــول‬\n‫هــذا هــو جوابــي علــى الدعــوى وبعــرض ذلــك علــى املدعــي قــال إننــي‬\n‫ال اعلــم عــن ذلــك هكــذا أجــاب فوردنــا جــواب رئيــس كتابــة عــدل‬\n‫األحســاء األولــى برقــم ‪ 331926957‬يف ‪1433/11/01‬ه ـ املتضمــن أن‬\n‫الصــك محــل الدعــوى رقــم ‪ 3/1/2407‬يف ‪1427/08/03‬ه ـ مطابــق‬\n‫لســجله وســاري املفعــول كمــا جــرى اإلطــاع علــى العقــد الــذي بــن‬\n‫الطرفــن واملرفــق صــوره منــه يف املعاملــة املطبــوع علــى مطبوعــات بنــك‬\n\n\n                                                                                        ‫‪94‬‬\n\f     ‫‪ ...‬واملتضمــن متديــد العقــد بــن املالــك األول والبنــك مــدة خمــس ســنوات‬\n     ‫تبــدأ مــن تاريــخ ‪2007/08/01‬م ويتجــدد تلقائيــا ملــدة مماثلــة مالــم يقــم‬\n     ‫أحــد الطرفــن بإخطــار الطــرف األخــر خطيــا خــاف ذلــك قبــل ســنة‬\n     ‫ـاء علــى‬\n             ‫مــن تاريــخ إنتهــاء الفتــرة التعاقديــة إنتهــى مضمــون العقــد فبنـ ً‬\n     ‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث طالــب املدعــي برفــع يــد املدعــى‬\n     ‫عليهــا ودفعــت املدعــى عليهــا بــأن يدهــا يــد صحيحــة علــى األرض‬\n     ‫مبوجــب عقــد إيجــار مــع املالــك الســابق وصــادق املدعــي علــى العقــد‬\n     ‫الــذي أبرمــه املالــك الســابق وهــو والــده وقــرر إلتزامــه بــه وحيــث إن‬\n     ‫الشــرط املذكــور يف العقــد بــن املالــك األول واملدعــى عليهــا نــص علــى‬\n     ‫أن طلــب فســخ العقــد ال بــد أن يكــون مكتوبــا وقبــل ســنة مــن تاريــخ‬\n     ‫نهايــة العقــد وهــذا مالــم يحصــل مــن طــرف املدعــي ودفعــه عــدم علمــه‬\n     ‫بالشــرط غيــر مقبــول وليــس موجبــا لفســخ العقــد واألصــل يف العقــود‬\n     ‫والشــروط الصحــة وهــذا شــرط يف مصلحــة أحــد املتعاقديــن وليــس‬\n     ‫فيــه محــذور شــرعي والقاعــدة الشــرعية أنــه يلــزم مراعــاة الشــرط قــدر‬\n     ‫اإلمــكان والوفــاء بالشــرط داخــل ضمــن عمــوم الوفــاء بالعقــود لقولــه‬\n     ‫تعالــى (( يأيهــا الذيــن امنــوا أوفــوا بالعقــود )) وقولــه عليــه الصــاة‬\n     ‫والســام (( املســلمون علــى شــروطهم )) قــال ابــن رجــب ((يف القاعــدة‬\n     ‫السادســة والثالثــن مــن قواعــده بعــد كالم طويــل والقســم الثانــي أن‬\n     ‫تكــون إجارتــه مبلــك ثــم تنتقــل إلــى غيــره وهــو أنــواع وقــال يف ثانيهــا‬\n     ‫أن ينتقــل امللــك إلــى مــن خلفــه يف مالــه ويقــوم مقامــه ويتلقــى امللــك‬\n     ‫عنــه فــا اعتــراض لــه علــى عقــوده بــل هــو منفــذ لهــا وذلــك كالــوارث‬\n     ‫واملشــتري انتهــى كالمــه لذلــك كلــه فقــد حكمــت مبايلــي أوال ثبــت‬\n     ‫لــدي صحــة عقــد املدعــى عليهــا مــع املدعــي ملــدة خمــس ســنوات ميالديــة‬\n\n\n‫‪95‬‬\n\f‫مــن تاريــخ ‪2012/08/01‬م وتنتهــي يف ‪2017/07/31‬م ثانيــا صرفــت‬\n‫النظــر عــن دعــوى املدعــي جتــاه املدعــى عليهــا ثالثــا أفهمــت املدعــى‬\n‫عليهــا باخلــروج مــن العقــار محــل الدعــوى عنــد نهايــة املــدة مالــم يكــن‬\n‫هنــاك عقــد جديــد مــع املدعــي وبعــرض احلكــم علــى الطرفــن قنــع‬\n‫بــه املدعــى عليــه وكالــة وقــرر املدعــي معارضتــه علــى احلكــم وطلــب‬\n‫محكمــة اإلســتئناف فأفهمتــه مبراجعتنــا بتاريــخ ‪1433/11/21‬ه ـ‬\n‫الســتالم نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا‬\n‫مــن تاريــخ اســتالمه فــإذا مضــت املــدة دون تقــدمي اإلعتــراض اكتســب‬\n‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آله وصحبه وســلم ‪ .‬حرر يف ‪ 1433/11/13‬هـ يف متام الســاعة التاســعة‬\n                                                                      ‫صباح ـ ًا ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/03/03‬ه ـ‬\n‫حضــر املدعــي و املدعــى عليــه وكالــة املذكــورة هويتهمــا ســابقا وقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف املقيــدة بخطــاب رئيســها‬\n‫رقــم ‪ 3427618‬يف ‪1434/2/6‬ه ـ وبرفقــه القــرار رقــم ‪ 3426200‬يف‬\n‫‪1434/1/28‬ه ـ الصــادر مــن الدائــرة احلقوقيــة الثانيــة يف محكمــة‬\n‫االســتئناف يف املنطقــة الشــرقية ونــص املقصــود منــه بعــد املقدمــة‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫لوحــظ أن وكيــل البنــك قــد ذكــر يف األوراق املقدمــة منــه لفضيلــة‬\n‫القاضــي بأنــه مت تســديد أجــرة الســنة التــي بــدأت يف ‪2012/8/1‬م‬\n‫وقدرهــا ثالثمائــة ألــف ريــال ولــم جنــد أن فضيلــة القاضــي ناقــش ذلــك‬\n‫مــع الطرفــن فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال مــا يلــزم‬\n‫نحــوه بحضــور الطرفــن ثــم أال يــرى فضيلتــه عــرض الصلــح عليهمــا‬\n\n\n                                                                                    ‫‪96‬‬\n\f     ‫وحثهمــا عليــه ؟ واهلل املوفــق قاضــي االســتئناف وقاضــي االســتئناف‬\n     ‫ورئيــس الدائــرة وعليــه توقيــع وختــم كل واحــد منهــم انتهــى املقصــود‬\n     ‫منــه وعليــه فقــد عرضــت الصلــح علــى الطرفــن ومحاولــة تغييــر قيمــة‬\n     ‫العقــد مبــا يرضــي الطرفــن أو تعديــل مدتــه فقــال املدعــى عليــه إننــي‬\n     ‫أطلــب الرجــوع ملوكلتــي يف ذلــك ويف جلســة أخــرى حضــر املدعــي‬\n     ‫واملدعــى عليــه وبســؤال وكيــل املدعــى عليهــا عــن الصلــح مــع املدعــي‬\n     ‫حســب طلــب محكمــة االســتئناف فقــال إن الشــركة موكلتــي ال‬\n     ‫مانــع لديهــا مــن الصلــح بشــرط أن تســلم األرض بعــد ســنة وأن يتحمــل‬\n     ‫املدعــي تكاليــف أتعــاب حضــور البنــك جللســات الترافــع واملقــدرة‬\n     ‫مببلــغ ســبعة آالف وخمســمائة وأحــد عشــر ريــال وبعــرض ذلــك علــى‬\n     ‫املدعــي قــال إننــي ال أقبــل بذلــك وأطلــب تســليم األرض فــور ًا ثــم ســألت‬\n     ‫املدعــي هــل مت تســديد أجــرة الســنة التــي بــدأت يف ‪2012/8/1‬م فقــال‬\n     ‫لــم يتــم تســديد األجــرة حتــى اآلن فأفهمــت املدعــي بــأن لــه إقامــة دعــوى‬\n     ‫مســتقلة بخصــوص األجــرة متــى مــا رغــب يف ذلــك فاســتعد بذلــك وعليــه‬\n     ‫فإنــه لــم يظهــر لــي خــاف مــا حكمــت بــه ســابق ًا وأمــرت بإحلــاق ذلــك يف‬\n     ‫الصــك وســجله ثــم إعــادة املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                         ‫الســاعة التاســعة والنصــف وتاريــخ ‪ 1434/04/02‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪ 34927585‬وتاريــخ ‪1434/4/15‬ه ـ الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة اإلحســاء برقــم ‪34335332‬‬\n     ‫وتاريــخ‪1434/ 4/9‬ه ـ املرفــق بهاالصــك الصــادر مــن فضيلــة‬\n\n\n‫‪97‬‬\n\f‫القاضــي باحملكمــة الشــيخ‪ .......‬املســجل برقــم ‪ 33452634‬وتاريــخ‬\n‫‪1433/11/13‬ه ـ بشــأن دعــوى‪ .......‬ضــد البنــك ‪ ...‬يف قضيــة حقوقيــة‬\n‫وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n‫ســبق دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي علــى قرارنــا ذي‬\n‫الرقــم‪/3426200‬ق‪/2‬ب والتاريــخ ‪1434/1/28‬ه ـ قررنــا ـ ـ باالكثريــة‬\n‫ـ ـ املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/5/28‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪98‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":91,"source_page_end":98,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"27d4dbf8ee811b06f7824f05471e6ae26db5f9cad52b1f5437cb0307a67f093c","normalized_text_hash":"4a4b7fcda602e081391c9baaf5b587a8bc82ac20d5d4ce70b343ff374a0210ef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p91-33452634"},{"id":"574840cd-4394-5223-9b1b-70a4fef592f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار -االلتزام بشروط العقد -احلكم باستمرار العقد لتخلف شرط األخطار قبل انتهاء مدته -صرف النظر عن اإلخاء -تسليم مبلغ حال من اإليجار وتسليم املؤجل","document_number":"33456173","case_number":"33557758","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/16","year":"1434","subject":"عقد -إجارة -إخاء عقار -االلتزام بشروط العقد -احلكم باستمرار العقد لتخلف شرط األخطار قبل انتهاء مدته -صرف النظر عن اإلخاء -تسليم مبلغ حال من اإليجار وتسليم املؤجل","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1433/11/16 :‬هـ‬\n                      ‫ُ‬                 ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33456173 :‬‬\n                        ‫َر ْق ُم الدعوى‪33557758 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‬\n                ‫‪ 3448656:‬تاريخه‪1434/2/26 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار ‪ -‬االلتــزام بشــروط العقــد ‪ -‬احلكــم‬\n      ‫باســتمرار العقــد لتخلــف شــرط األخطــار قبــل انتهــاء مدتــه ‪ -‬صــرف‬\n      ‫النظــر عــن اإلخــاء ‪ -‬تســليم مبلــغ حــال مــن اإليجــار وتســليم املؤجــل‬\n                                                                   ‫عنــد حلولــه ‪.‬‬\n\n\n\n\n                            ‫قوله صلى اهلل عليه وسلم «املسلمون على شروطهم»‬\n\n\n\n\n      ‫ادعــى املدعــى ضــد املدعــى عليــه بأنــه اجــر الــدور األرضــي مــن عقــاره‬\n      ‫مببلــغ قــدره خمســه وعشــرون ألــف ريــال مــن ‪1429/6/1‬ه ـ وحتــى‬\n      ‫‪1430/6/1‬ه ـ وانــه تــرك املدعــى عليــه ســنتني وقــد طلــب منــه اخلــروج‬\n      ‫فلــم يخــرج وطلــب احلكــم علــى املدعــى عليــه باخلــروج مــن املنــزل وان‬\n      ‫يســدد األجــرة عــن الوقــت الــذي بقــى فيــه بعــد انتهــاء اإليجــار‪ ،‬أجــاب‬\n      ‫املدعــى عليــه باملصادقــة علــى الدعــوى وأضاف أن العقد يتجدد ســنويا‪،‬‬\n      ‫قــرر املدعــى انــه اخبــر املدعــى عليــه باخلــروج ولكــن قبــل نهايــة العقــد‬\n      ‫بأقــل مــن شــهر‪ ،‬مت اطــاع حاكــم القضيــة علــى العقــد فوجــد أن املــادة‬\n      ‫الثامنــة نصــت علــى أن يف حالــة إخــاء العقــار فعلــى احــد الطرفــن‬\n      ‫الراغــب يف اإلخــاء إشــعار اآلخــر قبــل نهايــة العقــد بشــهر كامــل وإذا‬\n‫‪99‬‬\n\f‫لــم يتــم ذلــك فيتجــدد العقــد تلقائيــا‪ ،‬تصــادق الطرفان علــى العقد‪،‬بناء‬\n‫علــى األســباب املرصــودة يف نــص القضيــة ولقولــه صلــى اهلل عليــه وســلم‬\n‫((املســلمون علــى شــروطهم))صدر احلكــم بــرد دعــوى املدعــى وإفهامــه‬\n‫بــأن للمدعــى عليــه االســتمرار يف إكمــال الســنة حتــى نهايتهــا كمــا‬\n‫صــدر احلكــم علــى املدعــى عليــه بــأن يســلم للمدعــى األجــرة احلالــة‬\n‫والباقــي عنــد حلولــه‪ ،‬قــرر املدعــى عليــه القناعــة‪ ،‬قــرر املدعــى عــدم‬\n‫القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف بالريــاض باملصادقــة علــى‬\n‫احلكــم‪ ،‬حضــر املدعــى وقــرر انــه اســتلم كامــل املبلــغ احملكــوم بــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم الثالثــاء املوافــق‪ 1433/11/16‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 08 : 15‬وفيهــا حضــر حامــل الســجل املدنــي رقــم وادعــى علــى‬\n‫احلاضــر معــه يف مجلــس احلكــم حامــل الســجل املدنــي رقــم قائــا‬\n‫يف دعــواه عليــه إننــي أجرتــه الــدور االرضــي يف عقــاري الكائــن يف‬\n‫حــي ‪ ...‬مبدينــة الريــاض والــذي أملكــه مبوجــب الصــك الصــادر مــن‬\n‫كتابــة العــدل برقــم ‪ 210117004183‬مببلــغ وقــدره خمســة وعشــرين‬\n‫ألــف ريــال ابتــداء مــن ‪1429/6/1‬ه ـ وينتهــي االيجــار يف ‪ 1430/6/1‬ه ـ‬\n‫ثــم اننــي تركــت املدعــي عليــه يف العقــار الســنة الثانيــة والتاليــة وقــد‬\n‫طلبــت منــه اخلــروج فلــم يخــرج فأطلــب احلكــم علــى املدعــى عليــه بــأن‬\n‫يخــرج مــن منزلــي وأن يســدد أجــرة الوقــت الــذي بقــي فيــه بعــد انتهــاء‬\n‫االيجــار يف ‪ ...‬لهــذا العــام ‪1433‬ه ـ هــذه دعــواي وبعرضهــا علــى املدعــى‬\n‫عليــه صــادق علــى ماجــاء يف الدعــوى واضــاف إن العقــد يتجــدد ســنويا‬\n\n                                                                                    ‫‪100‬‬\n\f      ‫تلقائيــا وبعــد ابتداءالســنة الثالثــة بعشــرة ايــام زاد زيــادة ألفــن ريــال يف‬\n      ‫االيجــار فرفضــت حيــث قــد ابتــدأت الســنة وأمــا جــاري الــذي يف األعلــى‬\n      ‫فوافــق علــى الزيــادة فلــم يتــم التعــرض عليــه ثــم إنــه بعــد املكاملــة األولــى‬\n      ‫باســبوع اتصــل بــي صاحــب املكتــب وطلــب منــي اخلــروج فرفضــت ثــم‬\n      ‫إن املدعــي اشــتكاني لــدى الشــرطة وامــا املقــدم املســتحق عليــه لهــذه‬\n      ‫الســنة والــذي قــدره اثنــا عشــر الــف ريــال وخمســمائة ريــال فقــد متــت‬\n      ‫تســليمه لــدى الشــرطة وأنــا مســتعد بــه اآلن وبســؤال املدعــي عــن وقــت‬\n      ‫تبليــغ املدعــى عليــه باخلــروج أجــاب لقــد مت تبليغــه وقــت نهايــة العقــد أو‬\n      ‫قبلــه بقليــل ولكــن ليــس قبــل شــهر هكــذا أجــاب ثــم جــرى االطــاع‬\n      ‫علــى العقــد فوجدتــه مــن مطبوعــات مكتــب ‪ ...‬للعقــارات برقــم ‪460‬‬\n      ‫يف ‪1429/6/5‬ه ـ وهــو بــن الطرفــن ونــص املــادة الثامنــة منــه ( إذا رأى‬\n      ‫أحــد الطرفــن إخــاء املــكان يف نهايــة العقــد فعليــه اشــعار الطــرف‬\n      ‫االخــر برغبتــه قبــل نهايــة العقــد بشــهر كامــل وإذا لــم يتــم ذلــك فيعتبــر‬\n      ‫العقــد متجــدد تلقائيــا ‪ .‬فجــرى عــرض العقــد علــى املدعــي فأجــاب إن‬\n      ‫هــذا العقــد الــذي بيننــا فلمــا تقــدم مــن الدعــوى واجلــواب وإلقــرار املدعي‬\n      ‫بصحــة العقــد املتضمــن العقــد املشــار اليــه واقــراره بانــه لــم يبلــغ املدعــى‬\n      ‫عليــه باخلــروج اال قبــل نهايــة العقــد باقــل مــن الشــهر والن املؤمنــون‬\n      ‫علــى شــروطهم فقــد رددت دعــوى املدعــي وأفهمتــه بــأن للمدعــى عليــه‬\n      ‫االســتمرار يف اكمــال الســنة املبتــدأة مــن ‪1433/6/1‬ه ـ حتــى نهايتهــا‬\n      ‫ثــم حكمــت علــى املدعــى عليــه بــأن يســلم املدعــي خمســة وعشــرين‬\n      ‫ألــف ريــال منهــا اثنــا عشــر ألــف وخمســمائة ريــال حالــة والباقــي عنــد‬\n      ‫حلــول القســط الثانــي يف ‪1433/12/1‬ه ـ وباجلميــع حكمــت وبعــرض‬\n      ‫ذلــك علــى الطرفــن قنــع بــه املدعــى عليــه ولــم يقنــع بــه املدعــي فقــررت‬\n\n\n‫‪101‬‬\n\f‫تســليمه صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه خــال‬\n‫فتــرة أقصاهــا ثالثــون يومــا فــإن تأخــر عــن ذلــك ســقط حقــه يف تقــدمي‬\n‫الالئحــة االعتراضيــة واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                            ‫‪ 1433/11/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يوم الســبت املوافــق ‪1434/3/21‬هـ افتتحت‬\n‫اجللســة وقــد وردت إلينــا املعاملــة مــن فضيلــة رئيس محكمة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 3448656‬وتاريــخ ‪1434/2/26‬ه ـ واملتضمــن انــه‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة‬\n‫قــررت الدائــرة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى تصحيــح‬\n‫مــامت التعليــم عليــه بالصــك قبــل بعثــه جلهــات التنفيــذ وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                              ‫‪1434/03/21‬هـ‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ فتحــت اجللســة وفيهــا املدعــي‬\n‫وقــرر بقولــه لقــد اســتلمت كامــل املبلــغ احملكــوم بــه وقــدره خمســة‬\n‫وعشــرون ألــف ريــال وذلــك مبوجــب الشــيك املصــدق املســحوب علــى‬\n‫مصــرف ‪ ...‬برقــم ‪ 252015‬تاريــخ ‪1434/4/22‬ه ـ وللبيــان جــرى إحلاقــه‬\n                                      ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعــت الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة لهــا مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد باخلطــاب رقــم‬\n‫‪ 331638412‬وتاريــخ بــدون املرفــق بهــا الصــك رقــم‪ 33456173‬وتاريــخ‬\n‫‪1433/11/16‬ه ـ الصــادر مــن فضيلــة القاضــي‪ .......‬املتضمــن احلكــم‬\n\n\n                                                                                     ‫‪102‬‬\n\f      ‫يف الدعــوى املقامــة مــن‪ .......‬ضــد‪ .......‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة قــررت الدائــرة املصادقــة علــى‬\n      ‫احلكــم مــع تنبيــه فضيلتــه إلــى تصحيــح مــا مت التعليــم عليــه بالصــك‬\n      ‫قبــل بعثــه جلهــات التنفيــذ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                             ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪103‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":99,"source_page_end":103,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f97a2414272fd358de9a23dcd296222c4fb33452f1c3059d2f192738d6d47824","normalized_text_hash":"9bcfb95983bb3e33fdf1aa52b06d92d0b334442c9141f6b05bcdec4b5321f824","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p99-33456173"},{"id":"0f49449c-1160-5d21-bfc8-28d6e185a85e","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -املطالبة بإخاء العقار النتهاء مدة اإلجارة -وجوب الوفاء بالعقود -احلكم بإخاء العقار -التماس -رفض االلتماس.","document_number":"33463120","case_number":"32217035","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"عقد -إجارة -املطالبة بإخاء العقار النتهاء مدة اإلجارة -وجوب الوفاء بالعقود -احلكم بإخاء العقار -التماس -رفض االلتماس.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/11/23 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33463120 :‬‬\n                    ‫َر ْق ُم الدعوى‪32217035 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 349075‬تاريخه‪1434/1/11 :‬هـ‬\n\n\n ‫عقــد ‪ -‬إجــارة ‪ -‬املطالبــة بإخــاء العقــار النتهــاء مــدة اإلجــارة ‪ -‬وجــوب‬\n ‫الوفــاء بالعقــود ‪ -‬احلكــم بإخــاء العقــار ‪ -‬التمــاس ‪ -‬رفــض االلتمــاس‪.‬‬\n\n\n\n\n                             ‫قوله تعالي « يا أيها الذين امنوا أوفوا بالعقود»‪.‬‬\n\n\n\n\n ‫دعــوى املدعــى وكالــة ضــد املدعــى عليــه وكالــة وتتضمــن دعــواه أن‬\n ‫موكلــه قــد اجــر للمدعــى عليهــا وكالــة فلته املوصوفــة يف نص القضية‬\n ‫بأجــرة ســنوية قدرهــا مائــة وعشــرون ألــف ريــال واملدعــى عليهــا أصالــة‬\n ‫لــم تقــم بســداد األجــرة وطلــب املدعــى وكالــة احلكــم علــى املدعــى‬\n ‫عليهــا بإخــاء العقــار موطــن الدعــوى‪ ،‬أجــاب املدعــى عليــه وكالــة‬\n ‫بــان مــا ذكــره املدعــى وكالــة غيــر صحيــح وقــرر أن الفــا قــد أخــذت‬\n ‫موكلتــه عليهــا مبلغــا مــن املــال عــن طريــق التــورق مــع شــخص أخــر وان‬\n ‫هنــاك دعــوى بهــذا اخلصــوص لــدى قاضــي آخــر‪ ،‬أجــاب املدعــى وكالــة‬\n ‫انــه ال عالقــة ملوكلــه مبــا دفــع بــه املدعــى عليــه وكالــة فالعقــد قــد‬\n ‫ابــرم مــع املدعــى عليهــا وصــك امللكيــة مســجل باســم موكلــه‪ ،‬وابــرز‬\n ‫عقــد اإليجــار وصــك امللكيــة ومضمونــه مــا جــاء يف الدعــوى‪ ،‬طلــب‬\n ‫ناظــر القضيــة مــن املدعــى عليــه وكالــة مــا يثبــت وجــود الدعــوى التــي‬\n                                                                                    ‫‪104‬‬\n\f      ‫ذكرهــا يف إجابتــه فقــدم أوراقـ ًا ليــس فيهــا مــا يؤيــد صحــة قولــه‪ ،‬قــرر‬\n      ‫ناظــر القضيــة انــه بنــاء علــى العقــد املبــرم بــن الطرفــن وقــد مضــت‬\n      ‫مــدة علــى انتهائــه ولقولــه تعالــى «يــا أيهــا الذيــن امنــوا أوفــوا بالعقــود»‬\n      ‫فقــد صــدر احلكــم علــى املدعــى عليهــا أصالــة بإخــاء العقــار موطــن‬\n      ‫الدعــوى وتســليمه للمدعــى‪ ،‬اعتــرض املدعــى عليــه‪ ،‬صــدق احلكــم مــن‬\n      ‫محكمــة االســتئناف‪ ،‬قــدم املدعــى عليــه وكالــه التماس ـ ًا حملكمــة‬\n                                                       ‫االســتئناف‪ ،‬رفــض االلتمــاس ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32217035‬وتاريــخ‬\n      ‫‪1432/06/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32676667‬وتاريــخ‬\n      ‫‪1432/06/08‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪ 1432/10/15‬هـ أفتتحت‬\n      ‫اجللســة وفيهــا حضــر املدعــي وكالــة ‪ .......‬ســعودي مبوجــب ســجل رقــم‬\n      ‫‪ .......‬الوكيــل عــن ‪ .......‬ســعودي مبوجــب ســجل رقــم ‪ .......‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة بجنــوب جــدة برقــم ‪20113‬‬\n      ‫وتاريــخ ‪ 1432/06/05‬ه ـ واملخــول لــه حــق املرافعــة واملدافعــة والقناعــة‬\n      ‫باألحــكام واالعتــراض عليهــا وحضــر حلضــوره ‪ .......‬ســعودي مبوجــب‬\n      ‫ســجل رقــم ‪ .......‬وبســؤال هــذا األخيــر عــن صفتــه أجــاب قائــا إننــي ابــن‬\n      ‫املدعــى عليهــا ولــم أحضــر مــا يخولنــي الترافــع عنهــا ومســتعد بإحضــار‬\n      ‫ذلــك يف اجللســة القادمــة وقــد قــرر احلاضــران طلــب تأجيــل اجللســة‬\n      ‫لوجــود بــوادر صلــح بينهمــا فأجيبــا لطلبهمــا وتقــرر رفــع اجللســة لذلــك‬\n‫‪105‬‬\n\f‫وتأجيلهــا إلــى يــوم األحــد املوافــق ‪1433/02/07‬ه ـ وبــاهلل التوفيــق ثــم‬\n‫بتاريــخ ‪1433/02/07‬ه ـ افتتحــت اجللســة وفيهــا حضــر حضــر املدعــي‬\n‫وكالــة وحضــر حلضــوره املدعــى عليــه وكالــة ‪ ....... ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .......‬الوكيــل الشــرعي عــن و مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة عــدل جــدة الثانيــة برقــم ‪ 25230‬وتاريــخ‬\n‫‪1432/04/08‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة وقبول األحكام‬\n‫واالعتــراض عليهــا وبســؤال املدعــي وكالــة عــن دعــواه أجــاب قائــا إن‬\n‫موكلــي ميلــك الفــا التــي يف حــي ‪ ...‬يف مدينــة جــدة وقــد قــام بتأجيرهــا‬\n‫علــى املدعــى عليهــا منــذ تاريــخ ‪1429/01/01‬ه ـ بأجــرة ســنوية قدرهــا‬\n‫مائــة وعشــرون ألــف ريــال وحتــى هــذا اليــوم لــم تقــم املدعــى عليهــا‬\n‫بســداد األجــرة املترتبــة علــى مكوثهــا لــذا نطلــب مــن فصيلتكــم‬\n‫احلكــم علــى املدعــى عليهــا وإلزامهــا بإخــاء الفــا محــل النــزاع هــذه‬\n‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي أجــاب قائــا‬\n‫إن مــا ذكــره املدعــي وكالــة يف دعــواه كلــه غيــر صحيــح فهــذه الفــا‬\n‫قــد أخــذت موكلتــي عليهــا مبلغــا مــن املــال عــن طريــق التــورق وذلــك‬\n‫مــع املدعــو وهنــاك دعــوى مقامــة بهــذا اخلصــوص لــدى فضيلــة القاضــي‬\n‫يف هــذه احملكمــة الشــيخ ومــا زالــت حتــت النظــر ندعــي فيهــا علــى‬\n‫املدعــو هكــذا أجــاب وبســؤال املدعــي وكالــة عمــا ذكــره املدعــى‬\n‫عليــه وكالــة أجــاب قائــا ال عالقــة ملوكلــي مبــا ذكــره املدعــى عليــه‬\n‫وكالــة فموكلــي قــد أبــرم عقــد اإليجــار مــع املدعــى عليهــا وصــك‬\n‫ملكيــة األرض التــي عليهــا الفــا مســجل باســم موكلــي وأبــرز مــن‬\n‫يــده العقــد املتضمــن‪ :‬أنــه يف يــوم اخلميــس ‪1429/01/01‬ه ـ املوافــق‬\n‫‪2008/01/10‬م قــد مت االتفــاق بــن كل مــن‪ -1 :‬طــرف أول (مؤجــر)‬\n\n\n                                                                                   ‫‪106‬‬\n\f      ‫‪ -2‬الســيدة‪ ،.......‬وميثلهــا يف هــذا العقــد‪ /‬طــرف ثانــي ( مســتأجر) حيــث‬\n      ‫ميتلــك الطــرف األول الفــا الكائنــة بشــارع ‪ ...‬مبوجــب الصــك رقــم (‪)...‬‬\n      ‫وتاريــخ ‪1413/05/15‬ه ـ ويرغــب الطــرف الثانــي يف اســتئجارها‪،‬‬\n      ‫فقــد عايــن الفــا محــل العقــد املعاينــة التامــة النافيــة للجهالــة واتفــق‬\n      ‫الطرفــان وهمــا بكامــل أهليتهمــا املعتبــرة شــرعا علــى بنــود موضحــة‬\n      ‫يف العقــد املرفقــة صورتــه يف أوراق املعاملــة كمــا أبــرز مــن يــده‬\n      ‫صــورة الصــك الصــادرة مــن كتابــة عــدل جــدة األولــى برقــم ‪118‬‬\n      ‫وتاريــخ ‪1413/5/15‬ه ـ واملســجل باســم املدعــو‪ ...‬ومــا ذكــره املدعــى‬\n      ‫عليــه وكالــة مــن شــأن عالقــة موكلتــه باملدعــو فــإن هــذا ال عالقــة‬\n      ‫ملوكلــي بــه وإن كان للمدعــى عليهــا دعــوى علــى فلتواصــل دعواهــا‬\n      ‫بشــأن ذلــك وبســؤال املدعــى عليــه وكالــة عمــا يثبــت تعامــل موكلتــه‬\n      ‫مــع املدعــو بخصــوص هــذه الفــا محــل النــزاع فأجــاب قائــا أطلــب‬\n      ‫اإلمهــال إلحضــار مــا يثبــت ذلــك فأجيــب لطلبــه كمــا أفهــم املدعــي‬\n      ‫وكالــة بإحضــار أصــل الصــك فاســتعد لذلــك وتقــرر رفــع اجللســة لذلــك‬\n         ‫وتأجيلهــا إلــى يــوم األحــد املوافــق ‪1433/05/16‬ه ـ وبــاهلل التوفيــق ‪.‬‬\n      ‫ثــم بتاريــخ ‪1433/05/16‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫وكالــة ولــم حتضــر املدعــى عليهــا وال مــن ميثلهــا بوكالــة شــرعية وقــد‬\n      ‫حضــر حلضــوره املدعــو ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ .......‬وبســؤال األخيــر عــن صفتــه أجــاب قائــا إننــي ووكيــل عــن‬\n      ‫زوج املدعــى عليهــا ولــم أمتكــن مــن إحضــار وكالــة عــن املدعــى عليهــا‬\n      ‫وأطلــب اإلمهــال إلحضارهــا يف اجللســة القادمــة فأجيــب لطلبــه وبســؤال‬\n      ‫املدعــي وكالــة عمــا طلــب املهلــة ألجلــه أبــرز مــن يــده الصــك الصــادر‬\n      ‫مــن كتابــة عــدل جــدة األولــى برقــم وتاريــخ وقــد تقــرر بعثــه إلــى كتابــة‬\n\n\n‫‪107‬‬\n\f‫عــدل جــدة األولــى لالستفســار عــن ســجله وهــل يوجــد مايؤثــر عليــه‬\n‫كمــا جــرى إفهــام املدعــو ‪ ...‬بــأن عليــه إحضــار مــا يثبــت تعامــل املدعــى‬\n‫عليهــا مــع املدعــو يف هــذه الفــا محــل ففهــم ذلــك وأســتعد لــه وطلــب‬\n‫اإلمهــال وتقــرر رفــع اجللســة لذلــك وتأجيلهــا إلــى يــوم االثنــن املوافــق‬\n‫‪1433/11/22‬ه ـ الســاعة التاســعة صباحــا وبــاهلل التوفيــق ثــم بتاريــخ‬\n‫‪1433/11/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة وحضــر‬\n‫حلضــوره املدعــى عليــه وكالــة وقــد وردنــا خطــاب فضيلــة رئيــس كتابــة‬\n‫عــدل جــدة األولــى ذي الرقــم ‪ 33986899‬وتاريــخ ‪1433/06/04‬ه ـ‬\n‫واملتضمــن ( أنــه بالبحــث يف ســجالت اإلدارة لدينــا تبــن أن الصــك‬\n‫املرفــق رقــم ( ‪ ) ...‬يف ‪1413/05/15‬ه ـ ســاري املفعــول وال يوجــد مــا‬\n‫يؤثــر عليــه حتــى تاريخــه واهلل يحفظكــم ) أ‪.‬ه ـ ‪ ،‬وقــد جــرى تســليم‬\n‫املدعــي وكالــة أصــل الصــك املشــار إليــه بعاليــه وبســؤال األخيــر عمــا‬\n‫طلــب املهلــة ألجلــه أبــرز مــن يــده مجموعــة أوراق مطبوعــة علــى أوراق‬\n‫مؤسســة ‪ ...‬وبعــد اإلطــاع عليهــا ظهــر أنهــا تتعلــق بعقــار رقــم صكــه‬\n‫وتاريخــه ‪1408/11/12‬ه ـ وقــد جــرى إرفــاق مــا قدمــه املدعــى عليــه‬\n‫وكالــة يف املعاملــة فجــرى ســؤال املدعــى عليــه وكالــة وإفهامــه بــأن‬\n‫هــذه األوراق التــي قدمهــا تتعلــق بعقــار آخــر غيــر العقــار محــل الدعــوى‬\n‫فأجــاب قائــا إن املدعــي أصالــة هــو موظــف عنــد‪ ...‬فجــرى إفهامــه بــأن‬\n‫هــذا غيــر مؤثــر وقــد جــرى ســؤاله مــرة أخــرى وهــل لديــه مــا يثبــت مــا‬\n‫ادعــاه مــن وجــود خصومــة وتعامــل بخصــوص هــذا العقــار مــع املدعــو‬\n‫فأبــرز مجموعــة مــن األوراق جــرى إرفاقهــا يف املعاملــة تتعلــق بعقــود بــن‬\n‫املدعــى عليــه وبــن‪ ...‬ال عالقــة لهــا بالعقــار محــل النــزاع وقد جــرى إرفاق‬\n‫هــذه األوراق يف املعاملــة وبســؤال املدعــى عليــه وهــل لديــه ســوى مــا تقدم‬\n\n\n                                                                                     ‫‪108‬‬\n\f      ‫بــه فأجــاب قائــا ليــس لــدي ســوى مــا تقدمــت بــه وبعــد اإلطــاع علــى‬\n      ‫العقــد املبــرم بــن الطرفــن ظهــر أن نهايتــه بتاريــخ ‪1430/01/01‬ه ـ‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث إن املدعــي يطالــب‬       ‫فبنـ ً‬\n      ‫املدعــى عليــه إخــاء العقــار محــل النــزاع بعــد انتهــاء مــدة العقــد وإلزامــه‬\n      ‫بذلــك وحيــث إن املدعــى عليــه قــد دفــع بوجــود تعامــل ونــزاع يف هــذا‬\n      ‫العقــار مــع املدعــو وحيــث إن املدعــى عليــه لــم يتقــدم مبــا يثبــت وجــود‬\n      ‫هــذا النــزاع يف هــذا العقــار محــل الدعــوى وإمنــا تقــدم بــأوراق أخــرى ال‬\n      ‫تثبــت صحــة دعــواه وحيــث أن العقــد املبــرم بــن الطرفــن ظاهــر بينهمــا‬\n      ‫وقــد مضــت فتــرة طويلــة علــى انتهائــه وحيــث إن مــن املتقــرر بالشــريعة‬\n      ‫وجــوب الوفــاء بالعقــود عمــا بقــول اهلل تعالــى ( يــا أيهــا الذيــن أمنــوا‬\n      ‫أوفــوا بالعقــود) جلميــع مــا تقــدم فقــد حكمــت علــى املدعــى عليهــا‬\n      ‫بإخــاء العقــار املوصــوف يف الدعــوى واململــوك لصالــح املدعــي وأمرتهــا‬\n      ‫بتســليمه للمدعــي وبعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة‬\n      ‫القناعــة وقــرر املدعــى عليــه وكالــة عــدم القناعــة بــه وأفهمــت املدعــى‬\n      ‫عليــه وكالــة مبراجعــة احملكمــة يــوم الســبت املوافــق ‪1433/11/27‬ه ـ‬\n      ‫الســتالم نســخة مــن احلكــم لالعتــراض عليــه ففهــم ذلــك واســتعد لــه‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                           ‫حــرر يف ‪1433/11/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد جــرى اإلطــاع علــى الالئحــة االعتراضيــة‬\n      ‫املقدمــة مــن املدعــي وكالــة واملقيــدة يف هــذه احملكمــة برقــم‬\n      ‫‪ 33/2259453‬وتاريــخ ‪1433/12/27‬ه ـ ولــم أجــد فيهــا مــا يؤثــر علــى‬\n      ‫مــا حكمــت بــه ‪ ،‬عليــه فقــد أمــرت برفــع كامــل أوراق املعاملــة إلــى‬\n      ‫محكمــة االســتئناف عمــا بالنظــام وبــاهلل التوفيــق وصلــى اهلل علــى‬\n\n\n‫‪109‬‬\n\f‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/12/28‬ه ـ ‪،،.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 34/3439767‬وتاريــخ‬\n‫‪1434/01/17‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 34/188111‬وتاريــخ‬\n‫‪1434/01/21‬ه ـ واملصدقــة مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة محكمــة االســتئناف رقــم ‪ 349075‬وتاريــخ ‪1434/01/11‬ه ـ‬\n‫املتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪.‬أ‪ .‬ه ـ ‪ ،‬قاضــي اســتئناف ‪ .......‬ختــم‬\n‫وتوقيــع وقاضــي اســتئناف ‪ .......‬ختــم وتوقيــع ورئيــس الدائــرة ‪.......‬‬\n‫ختــم وتوقيــع ‪ ،‬عليــه فقــد أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                       ‫يف ‪1434/01/24‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد افتتحــت اجللســة وقــد وردنــا خطــاب رئيــس‬\n‫محكمــة االســتئناف مبكــة املكرمــة املكلــف رقــم ‪34214381‬‬\n‫وتاريــخ ‪1434/02/23‬ه ـ واملقيــد بهــذه احملكمــة برقــم ‪34498811‬‬\n‫وتاريــخ ‪1434/02/27‬ه ـ بشــأن االلتمــاس املقــدم مــن وكالــة عــن‬\n‫املتضمــن طلبــه إعــادة النظــر يف احلكــم الصــادر مــن فضيلــة الشــيخ‬\n‫القاضــي باحملكمــة العامــة بجــدة برقــم ‪ 33463120‬وتاريــخ‬\n‫‪1433/01/11‬ه ـ املصــدق مــن محكمــة االســتئناف برقــم ‪349075‬‬\n‫وتاريــخ ‪1434/01/11‬ه ـ وبإحالــة أوراق املعاملــة للدائــرة احلقوقيــة‬\n‫الثانيــة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة صــدر قرارهــم‬\n‫رقــم ‪ 3427031‬وتاريــخ ‪1434/02/02‬ه ـ واملتضمــن مــا يلــي‪ :‬وبدراســة‬\n\n\n                                                                                   ‫‪110‬‬\n\f      ‫املعاملــة تقــرر باألكثريــة مــا يلــي ‪ -:‬أوال رفــض االلتمــاس املقــدم‬\n      ‫مــن املذكــور بعاليــه ‪ .‬ثانيــا ‪ -‬بنــاءا علــى املــادة ‪ 3/195‬مــن الالئحــة‬\n      ‫التنفيذيــة لنظــام املرافعــات الشــرعية فيــزود حاكــم القضيــة بصــورة‬\n      ‫مــن هــذا اإلقــرار إلكمــال الــازم وبــاهلل التوفيــق ‪.‬أ‪.‬ه ـ مــن الدائــرة‬\n      ‫احلقوقيــة الثانيــة قاضــي اســتئناف ختــم وتوقيــع وقاضــي اســتئناف ختــم‬\n      ‫وتوقيــع ورئيــس الدائــرة ختــم وتوقيــع ولــه وجهــة نظــر‪ .‬عليــه فقــد أمــرت‬\n      ‫بإحلــاق ذلــك بالضبــط وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/07/01‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بجــدة املســاعد برقــم ‪ 32/676667‬وتاريــخ‬\n      ‫‪1434/1/4‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي‬\n      ‫باحملكمــة العامــة بجــدة برقــم ‪ 33463120‬وتاريــخ ‪1433/11/23‬ه ـ ‪،‬‬\n      ‫املتضمــن دعــوى‪ ...‬ضــد‪ ، ...‬وبدراســة الصــك وصــورة ضبطــه والئحتــه‬\n      ‫االعتراضيــة تقــرر املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلى اهلل وســلم‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":104,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"52bb9b5d5e3bdd22449707ab129d3ca1f9eab178fdb1c35429c4982f41ee765d","normalized_text_hash":"2ac3500ee694bd69b100ff77fe5c2dedc504d91a71a290843e91e342b7def9af","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p104-33463120"},{"id":"5d81814c-b52a-5c82-b3be-d280f5e69593","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة استثماريه -تأجير شقق مفروشه للعزاب -الضرر من استخدام العقار يف غير محله -التأجير للعزاب يف حي يسكنه عوائل -الدفع بعدم الضرر -ثبوت الضرر عن طريق قسم اخلبراء- احلكم بإخاء العن .","document_number":"34256030","case_number":"33611853","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/1","year":"1434","subject":"عقد -إجارة استثماريه -تأجير شقق مفروشه للعزاب -الضرر من استخدام العقار يف غير محله -التأجير للعزاب يف حي يسكنه عوائل -الدفع بعدم الضرر -ثبوت الضرر عن طريق قسم اخلبراء- احلكم بإخاء العن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/7/1 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34256030 :‬‬\n                  ‫َر ْق ُم الدعوى‪33611853 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‬\n         ‫‪ 35315446:‬تاريخه‪1435/7/14 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة اســتثماريه ‪ -‬تأجيــر شــقق مفروشــه للعــزاب ‪ -‬الضــرر‬\n‫مــن اســتخدام العقــار يف غيــر محلــه ‪ -‬التأجيــر للعــزاب يف حــي يســكنه‬\n‫عوائــل ‪ -‬الدفــع بعــدم الضــرر ‪ -‬ثبــوت الضــرر عــن طريــق قســم اخلبراء‪-‬‬\n                                                   ‫احلكــم بإخــاء العــن ‪.‬‬\n\n\n\n\n          ‫الصامِ ـ ِـت رضــي اهلل عنــه قــال «أ ََّن َر ُســولَ َّ ِ‬\n‫الل َص َّلــى‬                                                     ‫‪ .1‬حديــث ُع َبــا َد َة ْبـ ِـن َّ‬\n                                                                                                          ‫ا ُ‬\n                ‫هلل َع َل ْ ِيــه َو َسـ َّل َم‪َ ،‬ق َضــى أَال َضـ َـر َر َو َل ِضـ َـرار» رواه ابــن ماجــه‪.‬‬\n‫‪ .2‬قــول شــيخ اإلســام ابــن تيميــة ‪-‬رحمــه اهلل تعالــى ‪ -‬يف مجمــوع‬\n‫الفتاوى(ج‪»:(181/34‬وقــد كان عمــر بــن اخلطــاب يأمــر العــزاب أال‬\n‫يســكنوا بــن املتأهلــن وأن ال يســكن املتأهــل بــن العــزاب ؛ وهكــذا فعــل‬\n‫املهاجــرون ملــا قدمــوا املدينــة علــى عهــد النبــي صلــى اهلل عليــه وســلم‬\n                 ‫ونفــوا شــابا خافــوا الفتنــة بــه مــن املدينــة إلــى البصــرة»‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بدعــوى ضــد املدعــى عليــه بقيامــه بتأجيــر العمــارة التــي‬\n‫يســتثمرها شــققا مفروشــة علــى عــزاب ولكونــه جــاره ولتضــرره مــن‬\n‫ذلــك فقــد طلــب منعــه مــن تأجيــره علــى العــزاب‪ ،‬أقــر املدعــى عليــه‬\n‫بتأجيــره الشــقق املفروشــة علــى شــركة تســكن عمــاال عزابــا ودفــع‬\n                                                                                                                ‫‪112‬‬\n\f      ‫بعــدم وجــود ضــرر علــى املدعــي‪ ،‬جــرى الكتابــة لقســم اخلبــراء فعــادت‬\n      ‫اإلفــادة بحصــر بعــض األضــرار وهــي‪ /1 :‬عــدم وجــود ترخيص إســكان‬\n      ‫شــقق مفروشــة ممــا يعنــي عــدم توفــر وســائل الســامة حــال حــدوث‬\n      ‫حريــق ؛ ‪/2‬وجــود الشــقق يف حــي ســكني ممــا يتســبب يف إزعــاج اجلــار‬\n      ‫وقــت الدخــول واخلــروج للشــقق؛‪/3‬ال يوجــد مواقــف خاصــة للشــقق ممــا‬\n      ‫يترتــب عليهــا ضيــق وازدحــام يف محيــط الشــقق‪ ،‬عليــه وملــا تضمنــه‬\n      ‫قــرار هيئــة النظــر مــن أضــرار وملــا ظهــر مــن عقــود املدعــى عليــه مــن أن‬\n      ‫املســتأجرين عــزاب و يؤجــر عليهــم بأجــرة يوميــة أو شــهرية‪ ،‬وملــا قــرره‬\n      ‫شــيخ اإلســام ابــن تيميــة ‪-‬رحمــه اهلل تعالــى ‪ -‬يف مجمــوع الفتــاوى (ج‬\n      ‫‪« :)181 /34‬وقــد كان عمــر بــن اخلطــاب يأمــر العــزاب أال يســكنوا‬\n      ‫بــن املتأهلــن وأن ال يســكن املتأهــل بــن العــزاب ؛ وهكــذا فعــل‬\n      ‫املهاجــرون ملــا قدمــوا املدينــة علــى عهــد النبــي صلــى اهلل عليــه وســلم‬\n      ‫ونفــوا شــابا خافــوا الفتنــة بــه مــن املدينــة إلــى البصــرة‪ ،‬و ألن «الضــرر‬\n      ‫الصامِ ـ ِـت رضــي اهلل عنــه قــال « َأ َّن َر ُســولَ َّ ِ‬\n      ‫الل‬                                                       ‫يــزال» فعــن ُع َبــا َد َة ْبـ ِـن َّ‬\n                                                                                                ‫َص َّلــى ُ‬\n      ‫اهلل َع َل ْي ـ ِه َو َس ـل ََّم‪ ،‬قَ َضــى َأال َضـ َـر َر َو َل ِضـ َـرار» رواه ابــن ماجــه‪،‬‬\n      ‫و ألن املدعــى عليــه ميكنــه اســتثمار العمــارة بطــرق االســتثمار األخــرى‬\n      ‫ومنهــا التأجيــر علــى العوائــل خــال فتــرة اســتئجاره للعمــارة فــا ضــرر‬\n      ‫عليــه لــذا فقــد حكمــت الدائــرة علــى الشــركة موكلــة املدعــى عليــه‬\n      ‫بإخــاء العمــارة محــل النــزاع‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..................‬القاضــي يف احملكمــة‬\n‫اجلزائية باخلبر وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 33611853‬وتاريــخ ‪1433/10/18‬ه‬\n‫املقيــدة باحملكمــة برقــم ‪ 331844681‬وتاريــخ ‪1433/10/18‬ه ـ يف‬\n‫يــوم األربعــاء املوافق‪1434/06/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 :15‬‬\n‫وفيهــا حضر‪...........................‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم……………‪..‬و حضــر حلضــوره‪ ......................‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )..................‬وادعــى األول علــى الثانــي‬\n‫قائــا إن املدعــى عليــه اســتأجر العمــارة الواقعــة بحــي ‪ ...‬بالبلــك رقــم‬\n‫‪ ...‬وأقــام باســتثمارها شــققا مفروشــة و يؤجرهــا علــى العــزاب و قــد‬\n‫تضررنــا مــن مجــاورة العــزاب وإزعاجهــم ومضايقتهــم لنــا فاحلــي عوائــل‬\n‫و جميــع ســاكني الشــقق مــن العــزاب ممــا ســبب لنــا حرجــا بالغــا وألن‬\n‫املدعــى عليــه ميكنــه اســتثمار الشــقق بطــرق أخــرى غيــر التأجيــر علــى‬\n‫العــزاب لــذا اطلــب احلكــم علــى املدعــى عليــه بعــدم التأجيــر علــى‬\n‫العــزاب ســواء كان التأجيــر يومــي أو أســبوعي أو شــهري أو ســنوي‬\n‫وســواء كان الشــقق مفروشــة أو غيــر مفروشــة وذلــك رفعــا للضــرر‬\n‫الواقــع علــي و علــى عائلتــي و علــى العوائــل الســاكنة باحلــي هــذه دعــواي‬\n‫وبــرد ذلــك للمدعــى عليــه أجــاب قائــا إننــي اســتأجرت العمــارة الواقعــة‬\n‫بحــي ‪ ...‬بالبلــك رقــم ‪ ....‬مــن مالكتــه املواطنــة‪ ........................../‬مــدة‬\n‫عشــر ســنوات بأجــرة ســنوية قدرهــا ثالثمائــة ألــف ريــال تبــدأ اعتبــارا‬\n‫مــن ‪1433/8/1‬ه ـ و اململــوك للمذكــورة مبوجــب صــك امللكيــة‬\n\n                                                                                          ‫‪114‬‬\n\f      ‫الصــادر مــن كتابــة عــدل الثقبــة برقــم ‪ 166‬بتاريــخ ‪1393/3/2‬ه ـ و‬\n      ‫املنتقــل إلــى ملكيــة املذكــورة مبوجــب التهميــش املظهــر علــى الصــك‬\n      ‫وقــد اســتثمرت العمــارة بتأجيرهــا شــقق مفروشــة علــى شــركات تقــوم‬\n      ‫بتســكني مهندســن وعمــال فيهــا و لــدي رخصــة مــن البلديــة و هــذا هــو‬\n      ‫حــال الشــارع الــذي تقــع عليــه العمــارة و ال ضــرر علــى املدعــي كمــا ورد‬\n      ‫بدعــواه هكــذا أجــاب هــذا و أبــرز املدعــى عليــه نســخ كربونيــة مــن‬\n      ‫عقــود اإليجــار املبرمــة بينــه و بــن الشــركات التــي أشــار إليهــا فوجدتــه‬\n      ‫بعضهــا تتضمــن تأجيــرا شــهريا و بعضهــا تأجيــر يومــي و جميعهــم‬\n      ‫عــزاب حســب مــا هــو مبــن بالعقــد و مــن اجلنســية الفلبينيــة و الهنديــة‬\n      ‫هــذا وجــرى االطــاع علــى عقــد اإليجــار املبــرم بــن مالكــة العمــارة و‬\n      ‫املدعــى عليــه وصــورة صــك امللكيــة املرفــق فوجدتهمــا كمــا ذكــر‬\n      ‫املدعــى عليــه هــذا وجــرى الكتابــة منــا إلــى هيئــة النظــر للوقــوف علــى‬\n      ‫املوقــع و اإلفــادة هــل يوجــد ضــرر منهــا علــى املدعــي فوردنــا قرارهــم‬\n      ‫رقــم ‪ ...‬يف ‪1434/5/5‬ه ـ املتضمــن {نفيدكــم أنــه مت اخلــروج إلــى العقــار‬\n      ‫محــل النــزاع فتــم حصــر بعــض األضــرار و هــي كالتالي‪/1:‬عــدم وجــود‬\n      ‫تراخيــص للشــقق الســكنية و هــذا يعنــي عــدم توفــر أدوات الســامة‬\n      ‫حــال حلــدوث حريــق ؛ ‪/2‬وجــود الشــقق يف حــي ســكني ممــا يتســبب‬\n      ‫يف إزعــاج اجلــار وقــت الدخــول واخلــروج للشــقق؛‪/3‬ال يوجــد مواقــف‬\n      ‫خاصــة للشــقق ممــا يترتــب عليهــا ضيــق و ازدحــام يف محيــط الشــقق}‬\n      ‫هــذا وبســؤال املدعــي عمــا ذكــره املدعــى عليــه مــن وجــود عــدد مــن‬\n      ‫العمائــر تــزاول نفــس النشــاط فقــرر قائــا إن جميــع العمائــر املخالفــة‬\n      ‫للنظــام ســوف نتقــدم بدعــوى ضدهــا و قــد تقدمــت بدعــوى ضــد اثنــن‬\n      ‫مــن أصحــاب الشــقق املفروشــة منهــم املدعــى عليــه هكــذا قــرر لــذا‬\n\n\n‫‪115‬‬\n\f‫وبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة و حيــث تضمــن قــرار هيئــة‬\n‫النظــر أنــه بعــد الوقــوف علــى املوقــع عــدم وجــود ترخيــص و عــدم توفــر‬\n‫أدوات الســامة ووجــود الشــقق يف حــي ســكني و عــدم وجــود مواقــف‬\n‫ممــا يترتــب عليهــا زحــام وضيــق و حيــث يتضــح مــن عقــود املدعــى عليــه‬\n‫أن املســتأجرين عــزاب و يؤجــر عليهــم يومــي أو شــهري وملــا قــرره شــيخ‬\n‫اإلســام ابــن تيميــة رحمــه اهلل تعالــى يف كتــاب مجمــوع الفتــاوى ج‬\n‫‪[ 181 /34‬وقــد كان عمــر بــن اخلطــاب يأمــر العــزاب أن ال تســكن‬\n‫بــن املتأهلــن وأن ال يســكن املتأهــل بــن العــزاب ؛ وهكــذا فعــل‬\n‫املهاجــرون ملــا قدمــوا املدينــة علــى عهــد النبــي صلــى اهلل عليــه وســلم‬\n‫ونفــوا شــابا خافــوا الفتنــة بــه مــن املدينــة إلــى البصــرة] و ألن الضــرر‬\n          ‫الصامِ ـ ِـت رضــي اهلل عنــه قــال { َأ َّن َر ُســولَ َّ ِ‬\n‫الل َص َّلــى‬                                                      ‫يــزال فعــن ُع َبــا َد َة ْبـ ِـن َّ‬\n                                                                                                    ‫ُ‬\n‫اهلل َع َل ْ ِيــه َو َسـل ََّم‪ ،‬قَ َضــى أَنْ َل َضـ َـر َر َو َل ِضـ َـرار} رواه ابــن ماجــة و حيــث‬\n‫أن املدعــى عليــه ميكنــه اســتثمار العمــارة بطــرق االســتثمار األخــرى و‬\n‫منهــا التأجيــر علــى العوائــل خــال فتــرة اســتئجاره للعمــارة فــا ضــرر‬\n‫عليهــا لــذا فقــد حكمــت علــى الشــركة موكلــة املدعــى عليــه بإخــاء‬\n‫العمــارة محــل النــزاع و بعــرض احلكــم عليــه قــرر عــدم القناعــة به وطلب‬\n‫متييــز احلكــم فأجبتــه لطلبــه و أفهمتــه باملراجعــة بتاريــخ ‪1434/6/26‬هـ‬\n‫الســتالم صــورة مــن صــك احلكــم فــإذا لــم يراجــع يف املوعــد احملــدد‬\n‫فســوف ميهــل بعــده ثالثــون يومــا إذا لــم يراجــع خاللهــا فــإن حقــه يف‬\n‫اســتئناف احلكــم يكــون ســاقط و صلــى اهلل علــى نبينــا محمــد و علــى‬\n‫آلــه وصحبــه وســلم حــرر يف ‪1432/2/21‬ه ـ احلمــد هلل وحــده وبعــد‬\n‫ففــي يــوم الثالثــاء املوافــق ‪1434/08/09‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪01.15‬وقــد مضــت املــدة النظاميــة لالعتــراض ولــم يحضــر املعتــرض‬\n\n\n                                                                                                            ‫‪116‬‬\n\f      ‫لتقــدمي الئحتــة االعتراضيــة وبــه يســقط حقــه يف االعتــراض ويكتســب‬\n      ‫احلكــم القطعيــة وقــد اصبــح باتــا واجــب التنفيــد وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/08/09‬ه ـ احلمــد هلل‬\n      ‫وحــده أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة الثانيــة‬\n      ‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة لــدى‬\n      ‫احملكمــة برقــم ‪ 342154890‬وتاريــخ ‪1434/9/9‬ه ـ الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم ‪341188853‬‬\n      ‫وتاريــخ ‪1434/9/2‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪.................... /‬املســجل برقــم ‪ 34256030‬وتاريــخ‬\n      ‫‪1434/7/1‬ه ـ اخلــاص بدعــوى‪ ...................... /‬ضــد‪.......................... /‬‬\n      ‫يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n              ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/12/3‬ه ـ ‪.‬‬\n\n\n\n\n‫‪117‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":112,"source_page_end":117,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef582fcc51c528d5517d817c4c30780e7a24b54c0f405f4322e6cb8c574dea5e","normalized_text_hash":"e7e713422060731ea092bcc5b24648aa089b4ace4458d26649e7311bb61ab192","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p112-34256030"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

